type ordera = Eqa | Lt | Gt;;

let rec compare_nat
  x y = (if less_nat x y then Lt else (if equal_nata x y then Eqa else Gt));;

let ccompare_nata : (nat -> nat -> ordera) option = Some compare_nat;;

