                             | MEq, MLessEq -> false
                             | MLessEq, MEq -> false
                             | MEq, MLess -> false
                             | MLess, MEq -> false
                             | MLessEq, MLessEq -> true
                             | MLess, MLess -> true
                             | MEq, MEq -> true;;

let equal_mconstraint = ({equal = equal_mconstrainta} : mconstraint equal);;

let equal_integer = ({equal = Z.equal} : Z.t equal);;

let ord_integer = ({less_eq = Z.leq; less = Z.lt} : Z.t ord);;

