                     | SRegexp, SFloat -> false
                     | SStr, SRegexp -> false
                     | SRegexp, SStr -> false
                     | SStr, SFloat -> false
                     | SFloat, SStr -> false
                     | SInt, SRegexp -> false
                     | SRegexp, SInt -> false
                     | SInt, SFloat -> false
                     | SFloat, SInt -> false
                     | SInt, SStr -> false
                     | SStr, SInt -> false
                     | SRegexp, SRegexp -> true
                     | SFloat, SFloat -> true
                     | SStr, SStr -> true
                     | SInt, SInt -> true;;

