                      | Any, Ge -> false
                      | Gta, Any -> false
                      | Any, Gta -> false
                      | Gta, Ge -> false
                      | Ge, Gta -> false
                      | Eqc, Any -> false
                      | Any, Eqc -> false
                      | Eqc, Ge -> false
                      | Ge, Eqc -> false
                      | Eqc, Gta -> false
                      | Gta, Eqc -> false
                      | Any, Any -> true
                      | Ge, Ge -> true
                      | Gta, Gta -> true
                      | Eqc, Eqc -> true;;

let equal_irel = ({equal = equal_irela} : irel equal);;

