let rec digits_of_nat
  n = (if less_nat n (Nat (Z.of_int 10))
        then [char_of_nat (plus_nata (Nat (Z.of_int 48)) n)]
        else digits_of_nat (divide_nat n (Nat (Z.of_int 10))) @
               [char_of_nat
                  (plus_nata (Nat (Z.of_int 48))
                    (modulo_nat n (Nat (Z.of_int 10))))]);;

let rec anon_name k = '\095' :: digits_of_nat k;;

let rec number_args
  x0 k = match x0, k with [], k -> ([], k)
    | t :: ts, k ->
        (if equal_trmb t (TVar ['\095'])
          then (let (tsa, a) = number_args ts (suc k) in
                 (TVar (anon_name (suc k)) :: tsa, a))
          else (let (tsa, a) = number_args ts k in (t :: tsa, a)));;

let rec number_pred
  p k = (let (ts, a) = number_args (snd p) k in ((fst p, ts), a));;

let rec number_f
  x0 k = match x0, k with
    FPred p, k -> (let (pa, a) = number_pred p k in (FPred pa, a))
    | FLet (p, f, g), k ->
        (let (pa, k1) = number_pred p k in
         let (fa, k2) = number_f f k1 in
         let (ga, a) = number_f g k2 in
          (FLet (pa, fa, ga), a))
    | FLetPast (p, f, g), k ->
        (let (pa, k1) = number_pred p k in
         let (fa, k2) = number_f f k1 in
         let (ga, a) = number_f g k2 in
          (FLetPast (pa, fa, ga), a))
    | FFrz (p, f, g), k ->
        (let (pa, k1) = number_pred p k in
         let (fa, k2) = number_f f k1 in
         let (ga, a) = number_f g k2 in
          (FFrz (pa, fa, ga), a))
    | FNeg f, k -> (let (fa, a) = number_f f k in (FNeg fa, a))
    | FAnd (f, g), k -> (let (fa, k1) = number_f f k in
                         let (ga, a) = number_f g k1 in
                          (FAnd (fa, ga), a))
    | FOr (f, g), k -> (let (fa, k1) = number_f f k in
                        let (ga, a) = number_f g k1 in
                         (FOr (fa, ga), a))
    | FImplies (f, g), k ->
        (let (fa, k1) = number_f f k in
         let (ga, a) = number_f g k1 in
          (FImplies (fa, ga), a))
    | FEquiv (f, g), k -> (let (fa, k1) = number_f f k in
                           let (ga, a) = number_f g k1 in
                            (FEquiv (fa, ga), a))
    | FExists (vs, f), k ->
        (let (fa, a) = number_f f k in (FExists (vs, fa), a))
    | FForAll (vs, f), k ->
        (let (fa, a) = number_f f k in (FForAll (vs, fa), a))
    | FAggreg (y, op, x, g, f), k ->
        (let (fa, a) = number_f f k in (FAggreg (y, op, x, g, fa), a))
    | FPrev (i, f), k -> (let (fa, a) = number_f f k in (FPrev (i, fa), a))
    | FNext (i, f), k -> (let (fa, a) = number_f f k in (FNext (i, fa), a))
    | FEventually (i, f), k ->
        (let (fa, a) = number_f f k in (FEventually (i, fa), a))
    | FOnce (i, f), k -> (let (fa, a) = number_f f k in (FOnce (i, fa), a))
    | FAlways (i, f), k -> (let (fa, a) = number_f f k in (FAlways (i, fa), a))
    | FPastAlways (i, f), k ->
        (let (fa, a) = number_f f k in (FPastAlways (i, fa), a))
    | FSince (i, f, g), k ->
        (let (fa, k1) = number_f f k in
         let (ga, a) = number_f g k1 in
          (FSince (i, fa, ga), a))
    | FTrigger (i, f, g), k ->
        (let (fa, k1) = number_f f k in
         let (ga, a) = number_f g k1 in
          (FTrigger (i, fa, ga), a))
    | FUntil (i, f, g), k ->
        (let (fa, k1) = number_f f k in
         let (ga, a) = number_f g k1 in
          (FUntil (i, fa, ga), a))
    | FRelease (i, f, g), k ->
        (let (fa, k1) = number_f f k in
         let (ga, a) = number_f g k1 in
          (FRelease (i, fa, ga), a))
    | FFrex (i, r), k -> (let (ra, a) = number_r r k in (FFrex (i, ra), a))
    | FPrex (i, r), k -> (let (ra, a) = number_r r k in (FPrex (i, ra), a))
    | FEqual (v, va), k -> (FEqual (v, va), k)
    | FLess (v, va), k -> (FLess (v, va), k)
    | FLessEq (v, va), k -> (FLessEq (v, va), k)
    | FSubstring (v, va), k -> (FSubstring (v, va), k)
    | FMatches (v, va, vb), k -> (FMatches (v, va, vb), k)
and number_r
  x0 k = match x0, k with
    RTest f, k -> (let (fa, a) = number_f f k in (RTest fa, a))
    | RConcat (r, s), k ->
        (let (ra, k1) = number_r r k in
         let (sa, a) = number_r s k1 in
          (RConcat (ra, sa), a))
    | RPlus (r, s), k -> (let (ra, k1) = number_r r k in
                          let (sa, a) = number_r s k1 in
                           (RPlus (ra, sa), a))
    | RStar r, k -> (let (ra, a) = number_r r k in (RStar ra, a))
    | RSkip v, k -> (RSkip v, k);;

let rec is_anon
  v = (match v with [] -> false | c :: _ -> ((c : char) = '\095'));;

let rec anon_vars
  p = maps (fun a ->
             (match a with TVar v -> (if is_anon v then [v] else [])
               | TCsta _ -> [] | TF2i _ -> [] | TI2f _ -> [] | TI2s _ -> []
               | TS2i _ -> [] | TF2s _ -> [] | TS2f _ -> []
               | TDayOfMonth _ -> [] | TMonth _ -> [] | TYear _ -> []
               | TFormatDate _ -> [] | TR2s _ -> [] | TS2r _ -> []
               | TPlus (_, _) -> [] | TMinus (_, _) -> [] | TUMinus _ -> []
               | TMult (_, _) -> [] | TDiv (_, _) -> [] | TMod (_, _) -> []))
        (snd p);;

let rec add_ex_f
  = function
    FPred p ->
      (if null (anon_vars p) then FPred p else FExists (anon_vars p, FPred p))
    | FLet (p, f, g) -> FLet (p, add_ex_f f, add_ex_f g)
    | FLetPast (p, f, g) -> FLetPast (p, add_ex_f f, add_ex_f g)
    | FFrz (p, f, g) -> FFrz (p, add_ex_f f, add_ex_f g)
    | FNeg f -> FNeg (add_ex_f f)
    | FAnd (f, g) -> FAnd (add_ex_f f, add_ex_f g)
    | FOr (f, g) -> FOr (add_ex_f f, add_ex_f g)
    | FImplies (f, g) -> FImplies (add_ex_f f, add_ex_f g)
    | FEquiv (f, g) -> FEquiv (add_ex_f f, add_ex_f g)
    | FExists (vs, f) -> FExists (vs, add_ex_f f)
    | FForAll (vs, f) -> FForAll (vs, add_ex_f f)
    | FAggreg (y, op, x, g, f) -> FAggreg (y, op, x, g, add_ex_f f)
    | FPrev (i, f) -> FPrev (i, add_ex_f f)
    | FNext (i, f) -> FNext (i, add_ex_f f)
    | FEventually (i, f) -> FEventually (i, add_ex_f f)
    | FOnce (i, f) -> FOnce (i, add_ex_f f)
    | FAlways (i, f) -> FAlways (i, add_ex_f f)
    | FPastAlways (i, f) -> FPastAlways (i, add_ex_f f)
    | FSince (i, f, g) -> FSince (i, add_ex_f f, add_ex_f g)
    | FTrigger (i, f, g) -> FTrigger (i, add_ex_f f, add_ex_f g)
    | FUntil (i, f, g) -> FUntil (i, add_ex_f f, add_ex_f g)
    | FRelease (i, f, g) -> FRelease (i, add_ex_f f, add_ex_f g)
    | FFrex (i, r) -> FFrex (i, add_ex_r r)
    | FPrex (i, r) -> FPrex (i, add_ex_r r)
    | FEqual (v, va) -> FEqual (v, va)
    | FLess (v, va) -> FLess (v, va)
    | FLessEq (v, va) -> FLessEq (v, va)
    | FSubstring (v, va) -> FSubstring (v, va)
    | FMatches (v, va, vb) -> FMatches (v, va, vb)
and add_ex_r = function RTest f -> RTest (add_ex_f f)
               | RConcat (r, s) -> RConcat (add_ex_r r, add_ex_r s)
               | RPlus (r, s) -> RPlus (add_ex_r r, add_ex_r s)
               | RStar r -> RStar (add_ex_r r)
               | RSkip v -> RSkip v;;

let rec def_ok p = null (anon_vars p);;

let rec tvars = function TVar v -> [v]
                | TCsta uu -> []
                | TF2i t -> tvars t
                | TI2f t -> tvars t
                | TI2s t -> tvars t
                | TS2i t -> tvars t
                | TF2s t -> tvars t
                | TS2f t -> tvars t
                | TDayOfMonth t -> tvars t
                | TMonth t -> tvars t
                | TYear t -> tvars t
                | TFormatDate t -> tvars t
                | TR2s t -> tvars t
                | TS2r t -> tvars t
                | TUMinus t -> tvars t
                | TPlus (t, u) -> tvars t @ tvars u
                | TMinus (t, u) -> tvars t @ tvars u
                | TMult (t, u) -> tvars t @ tvars u
                | TDiv (t, u) -> tvars t @ tvars u
                | TMod (t, u) -> tvars t @ tvars u;;

let rec pvars
  p = maps (fun a ->
             (match a with TVar v -> [v] | TCsta _ -> [] | TF2i _ -> []
               | TI2f _ -> [] | TI2s _ -> [] | TS2i _ -> [] | TF2s _ -> []
               | TS2f _ -> [] | TDayOfMonth _ -> [] | TMonth _ -> []
               | TYear _ -> [] | TFormatDate _ -> [] | TR2s _ -> []
               | TS2r _ -> [] | TPlus (_, _) -> [] | TMinus (_, _) -> []
               | TUMinus _ -> [] | TMult (_, _) -> [] | TDiv (_, _) -> []
               | TMod (_, _) -> []))
        (snd p);;

let rec fv_f
  = function FEqual (t, u) -> tvars t @ tvars u
    | FLess (t, u) -> tvars t @ tvars u
    | FLessEq (t, u) -> tvars t @ tvars u
    | FSubstring (t, u) -> tvars t @ tvars u
    | FMatches (t, u, ts) -> tvars t @ tvars u @ maps tvars (map_filter id ts)
    | FPred p -> pvars p
    | FLet (uu, uv, g) -> fv_f g
    | FLetPast (uw, ux, g) -> fv_f g
    | FFrz (uy, uz, g) -> fv_f g
    | FNeg f -> fv_f f
    | FAnd (f, g) -> fv_f f @ fv_f g
    | FOr (f, g) -> fv_f f @ fv_f g
    | FImplies (f, g) -> fv_f f @ fv_f g
    | FEquiv (f, g) -> fv_f f @ fv_f g
    | FExists (vs, f) ->
        filtera (fun v -> not (membera (equal_list equal_char) vs v)) (fv_f f)
    | FForAll (vs, f) ->
        filtera (fun v -> not (membera (equal_list equal_char) vs v)) (fv_f f)
    | FAggreg (y, va, vb, g, vc) -> y :: g
    | FPrev (vd, f) -> fv_f f
    | FNext (ve, f) -> fv_f f
    | FEventually (vf, f) -> fv_f f
    | FOnce (vg, f) -> fv_f f
    | FAlways (vh, f) -> fv_f f
    | FPastAlways (vi, f) -> fv_f f
    | FSince (vj, f, g) -> fv_f f @ fv_f g
    | FTrigger (vk, f, g) -> fv_f f @ fv_f g
    | FUntil (vl, f, g) -> fv_f f @ fv_f g
    | FRelease (vm, f, g) -> fv_f f @ fv_f g
    | FFrex (vn, r) -> fv_r r
    | FPrex (vo, r) -> fv_r r
and fv_r = function RSkip vp -> []
           | RTest f -> fv_f f
           | RConcat (r, s) -> fv_r r @ fv_r s
           | RPlus (r, s) -> fv_r r @ fv_r s
           | RStar r -> fv_r r;;

let rec superset _A xs = list_all (membera _A xs);;

let rec ok_f
  = function FLet (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FLetPast (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FFrz (p, f, g) -> def_ok p && (ok_f f && ok_f g)
    | FNeg f -> ok_f f
    | FAnd (f, g) -> ok_f f && ok_f g
    | FOr (f, g) -> ok_f f && ok_f g
    | FImplies (f, g) -> ok_f f && ok_f g
    | FEquiv (f, g) -> ok_f f && ok_f g
    | FExists (vs, f) -> not (null vs) && ok_f f
    | FForAll (vs, f) -> not (null vs) && ok_f f
    | FAggreg (y, op, x, g, f) ->
        membera (equal_list equal_char) (fv_f f) x &&
          (superset (equal_list equal_char) (fv_f f) g && ok_f f)
    | FPrev (uu, f) -> ok_f f
    | FNext (uv, f) -> ok_f f
    | FEventually (uw, f) -> ok_f f
    | FOnce (ux, f) -> ok_f f
    | FAlways (uy, f) -> ok_f f
    | FPastAlways (uz, f) -> ok_f f
    | FSince (va, f, g) -> ok_f f && ok_f g
    | FTrigger (vb, f, g) -> ok_f f && ok_f g
    | FUntil (vc, f, g) -> ok_f f && ok_f g
    | FRelease (vd, f, g) -> ok_f f && ok_f g
    | FFrex (ve, r) -> ok_r r
    | FPrex (vf, r) -> ok_r r
    | FEqual (v, va) -> true
    | FLess (v, va) -> true
    | FLessEq (v, va) -> true
    | FSubstring (v, va) -> true
    | FMatches (v, va, vb) -> true
    | FPred v -> true
and ok_r = function RTest f -> ok_f f
           | RConcat (r, s) -> ok_r r && ok_r s
           | RPlus (r, s) -> ok_r r && ok_r s
           | RStar r -> ok_r r
           | RSkip v -> true;;

let rec postprocess
  f = (let g = add_ex_f (fst (number_f f zero_nata)) in
        (if ok_f g then Some g else None));;

let rec times_int
  k l = Int_of_integer (Z.mul (integer_of_int k) (integer_of_int l));;

let rec plus_int
  k l = Int_of_integer (Z.add (integer_of_int k) (integer_of_int l));;

let rec minus_int
  k l = Int_of_integer (Z.sub (integer_of_int k) (integer_of_int l));;

let rec digit_val
  c = minus_int (Int_of_integer ((Z.of_int (Char.code c))))
        (Int_of_integer (Z.of_int 48));;

let rec nat_of_digits
  ds = foldl (fun n c ->
               plus_int (times_int (Int_of_integer (Z.of_int 10)) n)
                 (digit_val c))
         zero_int ds;;

let one_int : int = Int_of_integer (Z.of_int 1);;

let rec unit_factor
  c = (if ((c : char) = '\100')
        then times_int
               (times_int (Int_of_integer (Z.of_int 24))
                 (Int_of_integer (Z.of_int 60)))
               (Int_of_integer (Z.of_int 60))
        else (if ((c : char) = '\104')
               then times_int (Int_of_integer (Z.of_int 60))
                      (Int_of_integer (Z.of_int 60))
               else (if ((c : char) = '\109') then Int_of_integer (Z.of_int 60)
                      else one_int)));;

let rec butlast = function [] -> []
                  | x :: xs -> (if null xs then [] else x :: butlast xs);;

let rec units_of_lexeme
  s = times_int (unit_factor (last s)) (nat_of_digits (butlast s));;

let rec uminus_int k = Int_of_integer (Z.neg (integer_of_int k));;

let rec int_of_lexeme
  s = (match s with [] -> zero_int
        | c :: ds ->
          (if ((c : char) = '\045') then uminus_int (nat_of_digits ds)
            else nat_of_digits s));;

let rec span (Token_ext (tok, span, more)) = span;;

let rec s_txt (Span_ext (s_line, s_col, s_off, s_len, s_txt, more)) = s_txt;;

let rec lexeme t = s_txt (span t);;

let rec tok (Token_ext (tok, span, more)) = tok;;

let rec mfodl_dec_Units
  = function
    Nodea (dnv_Units, dxs_Units) ->
      (if equal_lista equal_char dnv_Units
            ['\085'; '\110'; '\105'; '\116'; '\115']
        then (match dxs_Units with [] -> None
               | [c_1] ->
                 (match
                   (match c_1
                     with Leafa dz_Units ->
                       (if equal_mtoka (tok dz_Units) TU
                         then Some (units_of_lexeme (lexeme dz_Units))
                         else None)
                     | Nodea (_, _) -> None)
                   with None ->
                     (match c_1
                       with Leafa dz_Unitsa ->
                         (if equal_mtoka (tok dz_Unitsa) INTEGER
                           then Some (int_of_lexeme (lexeme dz_Unitsa))
                           else None)
                       | Nodea (_, _) -> None)
                   | Some a -> Some a)
               | _ :: _ :: _ -> None)
        else None)
    | Leafa dwild_Units -> None;;

let rec mfodl_dec_RBound
  = function
    Nodea (dnv_RBound, dxs_RBound) ->
      (if equal_lista equal_char dnv_RBound
            ['\082'; '\066'; '\111'; '\117'; '\110'; '\100']
        then (match dxs_RBound with [] -> None | [_] -> None
               | [c_1; c_2] ->
                 (match
                   bind (mfodl_dec_Units c_1)
                     (fun dz_RBound ->
                       (match c_2
                         with Leafa dz_RBounda ->
                           (if equal_mtoka (tok dz_RBounda) RPA
                             then Some (OBnd dz_RBound) else None)
                         | Nodea (_, _) -> None))
                   with None ->
                     (match
                       bind (mfodl_dec_Units c_1)
                         (fun dz_RBoundb ->
                           (match c_2
                             with Leafa dz_RBoundc ->
                               (if equal_mtoka (tok dz_RBoundc) RSB
                                 then Some (CBnd dz_RBoundb) else None)
                             | Nodea (_, _) -> None))
                       with None ->
                         (match
                           (match c_1
                             with Leafa dz_RBoundd ->
                               (if equal_mtoka (tok dz_RBoundd) STAR
                                 then (match c_2
with Leafa dz_RBounde ->
  (if equal_mtoka (tok dz_RBounde) RPA then Some BInf else None)
| Nodea (_, _) -> None)
                                 else None)
                             | Nodea (_, _) -> None)
                           with None ->
                             (match c_1
                               with Leafa dz_RBoundf ->
                                 (if equal_mtoka (tok dz_RBoundf) STAR
                                   then (match c_2
  with Leafa dz_RBoundg ->
    (if equal_mtoka (tok dz_RBoundg) RSB then Some BInf else None)
  | Nodea (_, _) -> None)
                                   else None)
                               | Nodea (_, _) -> None)
                           | Some a -> Some a)
                       | Some a -> Some a)
                   | Some a -> Some a)
               | _ :: _ :: _ :: _ -> None)
        else None)
    | Leafa dwild_RBound -> None;;

let rec mfodl_dec_LBound
  = function
    Nodea (dnv_LBound, dxs_LBound) ->
      (if equal_lista equal_char dnv_LBound
            ['\076'; '\066'; '\111'; '\117'; '\110'; '\100']
        then (match dxs_LBound with [] -> None | [_] -> None
               | [c_1; c_2] ->
                 (match
                   (match c_1
                     with Leafa dz_LBound ->
                       (if equal_mtoka (tok dz_LBound) LPA
                         then (match c_2
                                with Leafa dz_LBounda ->
                                  (if equal_mtoka (tok dz_LBounda) INTEGER
                                    then Some (OBnd
        (int_of_lexeme (lexeme dz_LBounda)))
                                    else None)
                                | Nodea (_, _) -> None)
                         else None)
                     | Nodea (_, _) -> None)
                   with None ->
                     (match
                       (match c_1
                         with Leafa dz_LBoundb ->
                           (if equal_mtoka (tok dz_LBoundb) LPA
                             then (match c_2
                                    with Leafa dz_LBoundc ->
                                      (if equal_mtoka (tok dz_LBoundc) TU
then Some (OBnd (units_of_lexeme (lexeme dz_LBoundc))) else None)
                                    | Nodea (_, _) -> None)
                             else None)
                         | Nodea (_, _) -> None)
                       with None ->
                         (match c_1
                           with Leafa dz_LBoundd ->
                             (if equal_mtoka (tok dz_LBoundd) LSB
                               then bind (mfodl_dec_Units c_2)
                                      (fun dz_LBounde -> Some (CBnd dz_LBounde))
                               else None)
                           | Nodea (_, _) -> None)
                       | Some a -> Some a)
                   | Some a -> Some a)
               | _ :: _ :: _ :: _ -> None)
        else None)
    | Leafa dwild_LBound -> None;;

let rec mfodl_dec_Intv
  = function
    Nodea (dnv_Intv, dxs_Intv) ->
      (if equal_lista equal_char dnv_Intv ['\073'; '\110'; '\116'; '\118']
        then (match dxs_Intv with [] -> None | [_] -> None | [_; _] -> None
               | [c_1; c_2; c_3] ->
                 bind (mfodl_dec_LBound c_1)
                   (fun dz_Intv ->
                     (match c_2
                       with Leafa dz_Intva ->
                         (if equal_mtoka (tok dz_Intva) COM
                           then bind (mfodl_dec_RBound c_3)
                                  (fun dz_Intvb -> Some (dz_Intv, dz_Intvb))
                           else None)
                       | Nodea (_, _) -> None))
               | _ :: _ :: _ :: _ :: _ -> None)
        else None)
    | Leafa dwild_Intv -> None;;

let rec mfodl_dec_Var
  = function
    Nodea (dnv_Var, dxs_Var) ->
      (if equal_lista equal_char dnv_Var ['\086'; '\097'; '\114']
        then (match dxs_Var with [] -> None
               | [Leafa dz_Var] ->
                 (if equal_mtoka (tok dz_Var) NAME then Some (lexeme dz_Var)
                   else None)
               | [Nodea (_, _)] -> None | _ :: _ :: _ -> None)
        else None)
    | Leafa dwild_Var -> None;;

let rec mfodl_dec_Fun
  = function
    Nodea (dnv_Fun, dxs_Fun) ->
      (if equal_lista equal_char dnv_Fun ['\070'; '\117'; '\110']
        then (match dxs_Fun with [] -> None
               | [c_1] ->
                 (match
                   (match c_1
                     with Leafa dz_Fun ->
                       (if equal_mtoka (tok dz_Fun) F2I
                         then Some (fun a -> TF2i a) else None)
                     | Nodea (_, _) -> None)
                   with None ->
                     (match
                       (match c_1
                         with Leafa dz_Funa ->
                           (if equal_mtoka (tok dz_Funa) I2F
                             then Some (fun a -> TI2f a) else None)
                         | Nodea (_, _) -> None)
                       with None ->
                         (match
                           (match c_1
                             with Leafa dz_Funb ->
                               (if equal_mtoka (tok dz_Funb) DAY_OF_MONTH
                                 then Some (fun a -> TDayOfMonth a) else None)
                             | Nodea (_, _) -> None)
                           with None ->
                             (match
                               (match c_1
                                 with Leafa dz_Func ->
                                   (if equal_mtoka (tok dz_Func) MONTH
                                     then Some (fun a -> TMonth a) else None)
                                 | Nodea (_, _) -> None)
                               with None ->
                                 (match
                                   (match c_1
                                     with Leafa dz_Fund ->
                                       (if equal_mtoka (tok dz_Fund) YEAR
 then Some (fun a -> TYear a) else None)
                                     | Nodea (_, _) -> None)
                                   with None ->
                                     (match
                                       (match c_1
 with Leafa dz_Fune ->
   (if equal_mtoka (tok dz_Fune) FORMAT_DATE then Some (fun a -> TFormatDate a)
     else None)
 | Nodea (_, _) -> None)
                                       with None ->
 (match
   (match c_1
     with Leafa dz_Funf ->
       (if equal_mtoka (tok dz_Funf) R2S then Some (fun a -> TR2s a) else None)
     | Nodea (_, _) -> None)
   with None ->
     (match
       (match c_1
         with Leafa dz_Fung ->
           (if equal_mtoka (tok dz_Fung) S2R then Some (fun a -> TS2r a)
             else None)
