let rec mfodl_parse_tnum
  x = (fun a ->
        (match a with FALSE -> Nat (Z.of_int 44) | TRUE -> Nat (Z.of_int 43)
          | LPA -> Nat (Z.of_int 47) | RPA -> Nat (Z.of_int 63)
          | LSB -> Nat (Z.of_int 10) | RSB -> Nat (Z.of_int 11)
          | COM -> Nat (Z.of_int 49) | SC -> Nat (Z.of_int 2)
          | DOT -> Nat (Z.of_int 46) | QM -> Nat (Z.of_int 48)
          | LD -> Nat (Z.of_int 9) | LESSEQ -> Nat (Z.of_int 59)
          | EQa -> Nat (Z.of_int 60) | LESS -> Nat (Z.of_int 58)
          | GTR -> Nat (Z.of_int 57) | GTREQ -> Nat (Z.of_int 56)
          | STAR -> Nat (Z.of_int 52) | LARROW -> Nat (Z.of_int 12)
          | SUBSTRING -> Nat (Z.of_int 55) | MATCHES -> Nat (Z.of_int 61)
          | PLUS -> Nat (Z.of_int 54) | MINUS -> Nat (Z.of_int 53)
          | SLASH -> Nat (Z.of_int 51) | MOD -> Nat (Z.of_int 50)
          | F2I -> Nat (Z.of_int 42) | I2F -> Nat (Z.of_int 41)
          | DAY_OF_MONTH -> Nat (Z.of_int 40) | MONTH -> Nat (Z.of_int 39)
          | YEAR -> Nat (Z.of_int 38) | FORMAT_DATE -> Nat (Z.of_int 37)
          | R2S -> Nat (Z.of_int 36) | S2R -> Nat (Z.of_int 35)
          | I2S -> Nat (Z.of_int 34) | S2I -> Nat (Z.of_int 33)
          | F2S -> Nat (Z.of_int 32) | S2F -> Nat (Z.of_int 31)
          | NAME -> Nat (Z.of_int 26) | STR_CST -> Nat (Z.of_int 28)
          | REGEXP_CST -> Nat (Z.of_int 27) | INTEGER -> Nat (Z.of_int 30)
          | RAT -> Nat (Z.of_int 29) | TU -> one_nata | LET -> Nat (Z.of_int 25)
          | LETPAST -> Nat (Z.of_int 24) | FRZ -> Nat (Z.of_int 23)
          | IN -> Nat (Z.of_int 62) | NOT -> Nat (Z.of_int 45)
          | AND -> Nat (Z.of_int 68) | OR -> Nat (Z.of_int 69)
          | IMPL -> Nat (Z.of_int 71) | EQUIV -> Nat (Z.of_int 70)
          | EXISTS -> Nat (Z.of_int 14) | FORALL -> Nat (Z.of_int 13)
          | PREV -> Nat (Z.of_int 20) | NEXT -> Nat (Z.of_int 19)
          | EVENTUALLY -> Nat (Z.of_int 18) | ONCE -> Nat (Z.of_int 17)
          | ALWAYS -> Nat (Z.of_int 16) | PAST_ALWAYS -> Nat (Z.of_int 15)
          | SINCE -> Nat (Z.of_int 67) | TRIGGER -> Nat (Z.of_int 66)
          | UNTIL -> Nat (Z.of_int 65) | RELEASE -> Nat (Z.of_int 64)
          | BAR -> Nat (Z.of_int 72) | FREX -> Nat (Z.of_int 22)
          | PREX -> Nat (Z.of_int 21) | CNT -> Nat (Z.of_int 3)
          | MIN_KW -> Nat (Z.of_int 4) | MAX_KW -> Nat (Z.of_int 5)
          | SUM_KW -> Nat (Z.of_int 6) | AVG -> Nat (Z.of_int 7)
          | MED -> Nat (Z.of_int 8)))
        x;;

let mfodl_parse_i0 : nat = Nat (Z.of_int 319);;

let rec pt_pf (PTabs (x1, x2, x3, x4, x5, x6)) = x6;;

let rec lookup_num x0 uu = match x0, uu with NTip, uu -> None
                     | NNode (x, l, r), One -> x
                     | NNode (x, l, r), Bit0 k -> lookup_num l k
                     | NNode (x, l, r), Bit1 k -> lookup_num r k;;

let rec plus_num x0 x1 = match x0, x1 with One, One -> Bit0 One
                   | One, Bit0 n -> Bit1 n
                   | One, Bit1 n -> Bit0 (plus_num n One)
                   | Bit0 m, One -> Bit1 m
                   | Bit0 m, Bit0 n -> Bit0 (plus_num m n)
                   | Bit0 m, Bit1 n -> Bit1 (plus_num m n)
                   | Bit1 m, One -> Bit0 (plus_num m One)
                   | Bit1 m, Bit0 n -> Bit1 (plus_num m n)
                   | Bit1 m, Bit1 n -> Bit0 (plus_num (plus_num m n) One);;

let rec num_of_integer
  k = (if Z.leq k (Z.of_int 1) then One
        else (let (l, j) = divmod_integer k (Z.of_int 2) in
              let la = num_of_integer l in
              let lb = plus_num la la in
               (if Z.equal j Z.zero then lb else plus_num lb One)));;

let rec num_of_nat x = comp num_of_integer integer_of_nat x;;

let rec tlookup
  t n = (let NTab (z, tr) = t in
          (if equal_nata n zero_nata then z
            else lookup_num tr (num_of_nat n)));;

let rec pfinal
  p c = (let (kstk, v) = c in
          null v &&
            (match kstk with [] -> false
              | k :: _ ->
                equal_optiona equal_bool (tlookup (pt_pf p) k) (Some true)));;

let rec tenc f x = (x, f (tok x));;

let rec map_option f x1 = match f, x1 with f, None -> None
                     | f, Some x2 -> Some (f x2);;

let rec pt_N (PTabs (x1, x2, x3, x4, x5, x6)) = x5;;

let rec drop_as x0 ys = match x0, ys with [], ys -> ys
                  | uu :: xs, [] -> []
                  | uv :: xs, uw :: ys -> drop_as xs ys;;

let rec jget
  tab i k = (match tlookup tab i with None -> None | Some r -> tlookup r k);;

let rec ptarget
  p kstk a =
    (match a with PShift k -> Some (DShift, k :: kstk)
      | PReduce (pr, aa) ->
        (match drop_as (snd pr) kstk with [] -> None
          | k :: rest ->
            map_option (fun ka -> (DReduce pr, ka :: k :: rest))
              (jget (pt_N p) k aa)));;

let rec pt_E (PTabs (x1, x2, x3, x4, x5, x6)) = x4;;

let rec pecands
  p k = (match tlookup (pt_E p) k with None -> [] | Some es -> es);;

let rec pt_A (PTabs (x1, x2, x3, x4, x5, x6)) = x3;;

let rec pcands
  p k l = (match jget (pt_A p) k l with None -> [] | Some es -> es);;

let rec sfind
  f x1 = match f, x1 with f, [] -> None
    | f, a :: asa -> (match f a with None -> sfind f asa | Some aa -> Some aa);;

let rec pctl
  p c = (let (kstk, v) = c in
          (match kstk with [] -> None
            | k :: _ ->
              (match v
                with [] ->
                  map_option (fun (a, stk) -> (a, (stk, v)))
                    (sfind (ptarget p kstk) (pecands p k))
                | (_, l) :: va ->
                  map_option
                    (fun (a, stk) ->
                      (a, (stk, (match a with DShift -> va | DReduce _ -> v))))
                    (sfind (ptarget p kstk) (pcands p k l)))));;

let rec equal_dact _A _B
  x0 x1 = match x0, x1 with DShift, DReduce x2 -> false
    | DReduce x2, DShift -> false
    | DReduce x2, DReduce y2 ->
        equal_proda _A (equal_list (equal_prod (equal_sym _A _B) equal_irel)) x2
          y2
    | DShift, DShift -> true;;

let rec sresult tstk = (match tstk with [] -> None | t :: _ -> Some t);;

let rec take_as x0 uu = match x0, uu with [], uu -> []
                  | uv :: xs, [] -> []
                  | uw :: xs, y :: ys -> y :: take_as xs ys;;

let rec xtree
  dec act v tstk =
    (match act with DShift -> Leafa (dec (hda v)) :: tstk
      | DReduce pr ->
        Nodea (fst pr, rev (take_as (snd pr) tstk)) :: drop_as (snd pr) tstk);;

let rec bupd
  d stk =
    (let (sv, (c, p)) = d in
      (if equal_nata c p
        then (Some stk, (one_nata, times_nata (Nat (Z.of_int 2)) p))
        else (sv, (plus_nata c one_nata, p))));;

let rec brun _A _C _D
  ctl fin dec d st =
    (let (stk, (v, tstk)) = st in
      (if fin (stk, v) then sresult tstk
        else (if equal_optiona (equal_list _A) (fst d) (Some stk) then None
               else bind (ctl (stk, v))
                      (fun (act, (stka, va)) ->
                        brun _A _C _D ctl fin dec
                          (if equal_dact _C _D act DShift
                            then (None, (one_nata, one_nata)) else bupd d stk)
                          (stka, (va, xtree dec act v tstk))))));;

let rec mfodl_parse
  x = (fun w ->
        bind (brun equal_nat (equal_list equal_char) equal_mtok
               (pctl mfodl_parse_ptabs) (pfinal mfodl_parse_ptabs) fst
               (None, (one_nata, one_nata))
               ([mfodl_parse_i0], (mapa (tenc mfodl_parse_tnum) w, [])))
          mfodl_dec_Formula)
        x;;

let keyword_table : (char list * mtok) list
  = [(['\043'], PLUS); (['\045'], MINUS); (['\046'], DOT); (['\042'], STAR);
