      (['\060'; '\124'], PREX); (['\226'; '\151'; '\129'], PREX);
      (['\066'; '\065'; '\067'; '\075'; '\087'; '\065'; '\082'; '\068'], PREX);
      (['\077'; '\065'; '\084'; '\067'; '\072'; '\080'], PREX); (['\124'], BAR);
      (['\044'], COM); (['\059'], SC); (['\063'], QM); (['\095'], LD);
