      (['\061'], EQa); (['\077'; '\079'; '\068'], MOD);
      (['\102'; '\050'; '\105'], F2I); (['\105'; '\050'; '\102'], I2F);
      (['\105'; '\050'; '\115'], I2S); (['\115'; '\050'; '\105'], S2I);
      (['\102'; '\050'; '\115'], F2S); (['\115'; '\050'; '\102'], S2F);
      (['\068'; '\065'; '\089'; '\095'; '\079'; '\070'; '\095'; '\077'; '\079';
         '\078'; '\084'; '\072'],
        DAY_OF_MONTH);
      (['\077'; '\079'; '\078'; '\084'; '\072'], MONTH);
      (['\089'; '\069'; '\065'; '\082'], YEAR);
      (['\070'; '\079'; '\082'; '\077'; '\065'; '\084'; '\095'; '\068'; '\065';
         '\084'; '\069'],
        FORMAT_DATE);
      (['\070'; '\065'; '\076'; '\083'; '\069'], FALSE);
      (['\084'; '\082'; '\085'; '\069'], TRUE); (['\076'; '\069'; '\084'], LET);
      (['\076'; '\069'; '\084'; '\080'; '\065'; '\083'; '\084'], LETPAST);
      (['\070'; '\082'; '\090'], FRZ); (['\073'; '\078'], IN);
      (['\078'; '\079'; '\084'], NOT); (['\065'; '\078'; '\068'], AND);
      (['\079'; '\082'], OR);
      (['\073'; '\077'; '\080'; '\076'; '\073'; '\069'; '\083'], IMPL);
      (['\069'; '\081'; '\085'; '\073'; '\086'], EQUIV);
      (['\069'; '\088'; '\073'; '\083'; '\084'; '\083'], EXISTS);
      (['\070'; '\079'; '\082'; '\065'; '\076'; '\076'], FORALL);
      (['\080'; '\082'; '\069'; '\086'], PREV);
      (['\080'; '\082'; '\069'; '\086'; '\073'; '\079'; '\085'; '\083'], PREV);
      (['\078'; '\069'; '\088'; '\084'], NEXT);
      (['\069'; '\086'; '\069'; '\078'; '\084'; '\085'; '\065'; '\076'; '\076';
         '\089'],
        EVENTUALLY);
      (['\083'; '\079'; '\077'; '\069'; '\084'; '\073'; '\077'; '\069'; '\083'],
        EVENTUALLY);
      (['\079'; '\078'; '\067'; '\069'], ONCE);
      (['\065'; '\076'; '\087'; '\065'; '\089'; '\083'], ALWAYS);
      (['\080'; '\065'; '\083'; '\084'; '\095'; '\065'; '\076'; '\087'; '\065';
         '\089'; '\083'],
        PAST_ALWAYS);
      (['\072'; '\073'; '\083'; '\084'; '\079'; '\082'; '\073'; '\067'; '\065';
         '\076'; '\076'; '\089'],
        PAST_ALWAYS);
      (['\083'; '\073'; '\078'; '\067'; '\069'], SINCE);
      (['\084'; '\082'; '\073'; '\071'; '\071'; '\069'; '\082'], TRIGGER);
      (['\085'; '\078'; '\084'; '\073'; '\076'], UNTIL);
      (['\082'; '\069'; '\076'; '\069'; '\065'; '\083'; '\069'], RELEASE);
      (['\067'; '\078'; '\084'], CNT); (['\077'; '\073'; '\078'], MIN_KW);
      (['\077'; '\065'; '\088'], MAX_KW); (['\083'; '\085'; '\077'], SUM_KW);
      (['\065'; '\086'; '\071'], AVG); (['\077'; '\069'; '\068'], MED)];;

let rec is_letter
  c = (let k = (Z.of_int (Char.code c)) in
        Z.leq (Z.of_int 97) k && Z.leq k (Z.of_int 122) ||
          Z.leq (Z.of_int 65) k && Z.leq k (Z.of_int 90));;

let rec is_digit
  c = (let k = (Z.of_int (Char.code c)) in
        Z.leq (Z.of_int 48) k && Z.leq k (Z.of_int 57));;

let rec is_str_start c = is_letter c || (is_digit c || ((c : char) = '\095'));;

let rec sign_len
  s = (match s with [] -> zero_nata
        | c :: _ -> (if ((c : char) = '\045') then one_nata else zero_nata));;

let rec is_space c = membera equal_char ['\032'; '\009'; '\010'; '\013'] c;;

let rule_starts : (char -> bool) list
  = [is_space] @
      mapa (fun (k, _) c -> ((c : char) = (hda k))) keyword_table @
        [is_digit;
          (fun c -> not (equal_nata (sign_len [c]) zero_nata) || is_digit c);
          (fun c -> not (equal_nata (sign_len [c]) zero_nata) || is_digit c);
          (fun c -> ((c : char) = '\034')); (fun c -> ((c : char) = '\114'));
          is_str_start; (fun c -> ((c : char) = '\040'));
          (fun c -> ((c : char) = '\035'))];;

let rec is_str_char
  c = is_str_start c ||
        (membera equal_char ['\045'; '\047'; '\058'] c ||
          (((c : char) = '\039') || ((c : char) = '\034')));;

let rec takeWhile p x1 = match p, x1 with p, [] -> []
                    | p, x :: xs -> (if p x then x :: takeWhile p xs else []);;

let rec m_string
  s = (match s with [] -> None
        | c :: sa ->
          (if is_str_start c
            then Some (suc (size_lista (takeWhile is_str_char sa)))
            else None));;

let rec q_body
  = function [] -> None
    | c :: s ->
        (if ((c : char) = '\034') then Some one_nata
          else (if ((c : char) = '\092')
                 then (match s with [] -> None
                        | _ :: sa ->
                          map_option (fun n -> plus_nata n (Nat (Z.of_int 2)))
                            (q_body sa))
                 else map_option suc (q_body s)));;

let rec m_quoted
  s = (match s with [] -> None
        | c :: sa ->
          (if ((c : char) = '\034') then map_option suc (q_body sa)
            else None));;

let rec m_regexp
  s = (match s with [] -> None
        | c :: sa ->
          (if ((c : char) = '\114') then map_option suc (m_quoted sa)
            else None));;

let rec m_space
  s = (match s with [] -> None
        | c :: _ -> (if is_space c then Some one_nata else None));;

let rec starts_with _A x0 uu = match x0, uu with [], uu -> true
                         | uv :: uw, [] -> false
                         | a :: k, b :: s -> eq _A a b && starts_with _A k s;;

let rec m_fixed
  k s = (if not (null k) && starts_with equal_char k s then Some (size_lista k)
          else None);;

let rec count_digits
  = function [] -> zero_nata
    | c :: s -> (if is_digit c then suc (count_digits s) else zero_nata);;

let rec dropWhile p x1 = match p, x1 with p, [] -> []
                    | p, x :: xs -> (if p x then dropWhile p xs else x :: xs);;

let rec m_unit
  s = (let n = count_digits s in
        (if less_nat zero_nata n &&
              (match dropWhile is_digit s with [] -> false
                | c :: _ -> is_letter c)
          then Some (suc n) else None));;

let rec m_rat
  s = (let k = sign_len s in
       let t = drop k s in
       let n = count_digits t in
       let u = dropWhile is_digit t in
        (if less_nat zero_nata n &&
              (match u with [] -> false | c :: _ -> ((c : char) = '\046'))
          then Some (plus_nata (plus_nata (plus_nata k n) one_nata)
                      (count_digits (tla u)))
          else None));;

let rec m_int
  s = (let k = sign_len s in
       let n = count_digits (drop k s) in
        (if less_nat zero_nata n then Some (plus_nata k n) else None));;

let rules : ((char list -> nat option) * action) list
  = [(m_space, Skipa)] @
      mapa (fun (k, t) -> (m_fixed k, Emit t)) keyword_table @
        [(m_unit, EmitTU); (m_int, Emit INTEGER); (m_rat, Emit RAT);
          (m_quoted, Emit STR_CST); (m_regexp, Emit REGEXP_CST);
          (m_string, Emit NAME); (m_fixed ['\040'; '\042'], Comment);
          (m_fixed ['\035'], LineComment)];;

let rec rules_for
  c = map_filter
        (fun x -> (if (let (_, p) = x in p c) then Some (fst x) else None))
        (zip rules rule_starts);;

let rules_tab : (((char list -> nat option) * action) list) array
  = Array.of_list
      (mapa (fun i -> rules_for (char_of_nat i))
        (upt zero_nata (Nat (Z.of_int 256))));;

let rec best_match
  b x1 s = match b, x1, s with b, [], s -> b
    | b, (m, a) :: rs, s ->
        best_match
          (match m s with None -> b
            | Some n ->
              (match b with None -> Some (n, a)
                | Some (na, _) -> (if less_nat na n then Some (n, a) else b)))
          rs s;;

let rec lex_match
  s = (match s with [] -> None
        | c :: _ ->
          best_match None
            ((fun (a, i) -> Array.get a (Z.to_int i))
              (rules_tab, (Z.of_int (Char.code c))))
            s);;

let rec comment_end
  = function
    c :: d :: s ->
      (if ((c : char) = '\042') && ((d : char) = '\041')
        then Some (Nat (Z.of_int 2)) else map_option suc (comment_end (d :: s)))
    | [] -> None
    | [v] -> None;;

let rec valid_unit
  lx = membera equal_char ['\100'; '\104'; '\109'; '\115'] (last lx);;

let rec mk_token
  t off lx =
    Token_ext (t, Span_ext (zero_nata, off, off, size_lista lx, lx, ()), ());;

let rec line_end
  s = (let n =
         size_lista
           (takeWhile
             (fun c ->
               not (((c : char) = '\010')) && not (((c : char) = '\013')))
             s)
         in
        (if less_nat n (size_lista s) then suc n else n));;

let rec lex_aux
  uu uv x2 = match uu, uv, x2 with uu, uv, [] -> Some []
    | fuel, uw, v :: va ->
        (if equal_nata fuel zero_nata then None
          else (match lex_match (v :: va) with None -> None
                 | Some (n, a) ->
                   (let lx = take n (v :: va) in
                    let rest = drop n (v :: va) in
                     (match a
                       with Emit t ->
                         map_option (fun aa -> mk_token t uw lx :: aa)
                           (lex_aux (minus_nata fuel one_nata) (plus_nata uw n)
                             rest)
                       | Skipa ->
                         lex_aux (minus_nata fuel one_nata) (plus_nata uw n)
                           rest
                       | Comment ->
                         (match comment_end rest with None -> None
                           | Some k ->
                             lex_aux (minus_nata fuel one_nata)
                               (plus_nata (plus_nata uw n) k) (drop k rest))
                       | LineComment ->
                         (let k = line_end rest in
                           lex_aux (minus_nata fuel one_nata)
                             (plus_nata (plus_nata uw n) k) (drop k rest))
                       | EmitTU ->
                         (if valid_unit lx
                           then map_option (fun aa -> mk_token TU uw lx :: aa)
                                  (lex_aux (minus_nata fuel one_nata)
                                    (plus_nata uw n) rest)
                           else None)))));;

let rec lex s = lex_aux (size_lista s) zero_nata s;;

let rec parse_formula
  s = (match lex s with None -> None
        | Some w -> bind (mfodl_parse w) postprocess);;

let base_schema : (char list * (char list * sty) list) list
  = [(['\116'; '\112'], [(['\105'], SInt)]);
      (['\116'; '\115'], [(['\116'], SInt)]);
      (['\116'; '\112'; '\116'; '\115'],
        [(['\105'], SInt); (['\116'], SInt)])];;

let rec pend_toks = function L_SIMPLE s -> [T_STR s]
                    | L_INIT -> []
                    | L_QUOTED v -> []
                    | L_ESCAPE v -> []
                    | L_COMMENT -> [];;

let rec isLineCommentEnd c = ((c : char) = '\010') || ((c : char) = '\013');;

let rec isSimpleChar
  c = (('\048' : char) <= c) && ((c : char) <= '\057') ||
        ((('\065' : char) <= c) && ((c : char) <= '\090') ||
          ((('\097' : char) <= c) && ((c : char) <= '\122') ||
            (((c : char) = '\095') ||
              (((c : char) = '\091') ||
                (((c : char) = '\093') ||
                  (((c : char) = '\047') ||
                    (((c : char) = '\058') ||
                      (((c : char) = '\045') ||
                        (((c : char) = '\046') ||
                          ((c : char) = '\033'))))))))));;

let rec isWhiteSpace
  c = ((c : char) = '\032') ||
        (((c : char) = '\009') ||
          (((c : char) = '\010') || ((c : char) = '\013')));;

let rec lex_init
  c = (if isWhiteSpace c then Some ([], L_INIT)
        else (if ((c : char) = '\064') then Some ([T_AT], L_INIT)
               else (if ((c : char) = '\040') then Some ([T_LPAREN], L_INIT)
                      else (if ((c : char) = '\041')
                             then Some ([T_RPAREN], L_INIT)
                             else (if ((c : char) = '\060')
                                    then Some ([T_LANGLE], L_INIT)
                                    else (if ((c : char) = '\062')
   then Some ([T_RANGLE], L_INIT)
   else (if ((c : char) = '\123') then Some ([T_LBRACE], L_INIT)
          else (if ((c : char) = '\125') then Some ([T_RBRACE], L_INIT)
                 else (if ((c : char) = '\044') then Some ([T_COMMA], L_INIT)
                        else (if ((c : char) = '\059')
                               then Some ([T_SEMICOLON], L_INIT)
                               else (if ((c : char) = '\035')
                                      then Some ([], L_COMMENT)
                                      else (if ((c : char) = '\034')
     then Some ([], L_QUOTED [])
     else (if isSimpleChar c then Some ([], L_SIMPLE [c])
            else None)))))))))))));;

let rec lex_step
  c x1 = match c, x1 with c, L_INIT -> lex_init c
    | c, L_SIMPLE s ->
        (if isSimpleChar c then Some ([], L_SIMPLE (s @ [c]))
          else (if ((c : char) = '\034') && equal_lista equal_char s ['\114']
                 then Some ([], L_QUOTED [])
                 else map_option (apfst (fun a -> T_STR s :: a)) (lex_init c)))
    | c, L_QUOTED s ->
        (if ((c : char) = '\034') then Some ([T_STR s], L_INIT)
          else (if ((c : char) = '\092') then Some ([], L_ESCAPE (s @ [c]))
                 else Some ([], L_QUOTED (s @ [c]))))
    | c, L_ESCAPE s -> Some ([], L_QUOTED (s @ [c]))
    | c, L_COMMENT ->
        (if isLineCommentEnd c then Some ([], L_INIT)
          else Some ([], L_COMMENT));;

let rec lex_upto
  x0 l = match x0, l with [], l -> []
    | c :: s, l ->
        (match lex_step c l with None -> pend_toks l
          | Some (ts, la) -> ts @ lex_upto s la);;

let rec lex_finish = function L_INIT -> Some []
                     | L_SIMPLE s -> Some [T_STR s]
                     | L_QUOTED s -> None
                     | L_ESCAPE s -> None
                     | L_COMMENT -> Some [];;

let rec lex_run
  x0 l = match x0, l with [], l -> Some ([], l)
    | c :: s, l ->
        (match lex_step c l with None -> None
          | Some (ts, la) ->
            map_option (apfst (fun a -> ts @ a)) (lex_run s la));;

let rec sig_tokens
  s = (match lex_run s L_INIT
        with None -> mapa (fun a -> STok a) (lex_upto s L_INIT) @ [SErr]
        | Some (ts, l) ->
          (match lex_finish l with None -> mapa (fun a -> STok a) ts @ [SErr]
            | Some tsa -> mapa (fun a -> STok a) (ts @ tsa)));;

let rec squote s = '\039' :: s @ ['\039'];;

let rec tok_str
  = function [] -> ['\060'; '\069'; '\079'; '\070'; '\062']
    | SErr :: uu ->
        ['\060'; '\117'; '\110'; '\114'; '\101'; '\099'; '\111'; '\103'; '\110';
          '\105'; '\122'; '\101'; '\100'; '\062']
    | STok t :: uv ->
        (match t with T_AT -> squote ['\064'] | T_LPAREN -> squote ['\040']
          | T_RPAREN -> squote ['\041'] | T_LANGLE -> squote ['\060']
          | T_RANGLE -> squote ['\062'] | T_LBRACE -> squote ['\123']
          | T_RBRACE -> squote ['\125'] | T_COMMA -> squote ['\044']
          | T_SEMICOLON -> squote ['\059']
          | T_STR s -> '\034' :: escaped s @ ['\034']);;

let rec expected
  what ts =
    SE_PARSE
      (['\069'; '\120'; '\112'; '\101'; '\099'; '\116'; '\101'; '\100';
         '\032'] @
        what @
          ['\032'; '\098'; '\117'; '\116'; '\032'; '\115'; '\097'; '\119';
            '\032'] @
            tok_str ts);;

let rec sig_more
  x0 acc = match x0, acc with
    [], acc ->
      Inl (expected
            (squote ['\044'] @
              ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
            [])
    | t :: ts, acc ->
        (match t
          with STok T_AT ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_LPAREN ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_RPAREN -> Inr (rev acc, ts)
          | STok T_LANGLE ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_RANGLE ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_LBRACE ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_RBRACE ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok T_COMMA ->
            (match ts
              with [] ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_AT :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_LPAREN :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_RPAREN :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_LANGLE :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_RANGLE :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_LBRACE :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_RBRACE :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_COMMA :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok T_SEMICOLON :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts)
              | STok (T_STR s) :: tsa -> sig_more tsa (s :: acc)
              | SErr :: _ ->
                Inl (expected
                      ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103']
                      ts))
          | STok T_SEMICOLON ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | STok (T_STR _) ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts))
          | SErr ->
            Inl (expected
                  (squote ['\044'] @
                    ['\032'; '\111'; '\114'; '\032'] @ squote ['\041'])
                  (t :: ts)));;

let rec sig_tuple
  ts = (match ts with [] -> Inl (expected (squote ['\040']) ts)
         | STok T_AT :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_LPAREN :: ts1 ->
           (match ts1
             with [] ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_AT :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_LPAREN :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_RPAREN :: ts2 -> Inr ([], ts2)
             | STok T_LANGLE :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_RANGLE :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_LBRACE :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_RBRACE :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_COMMA :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok T_SEMICOLON :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1)
             | STok (T_STR s) :: ts2 -> sig_more ts2 [s]
             | SErr :: _ ->
               Inl (expected
                     (['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
                        '\103'; '\032'; '\111'; '\114'; '\032'] @
                       squote ['\041'])
                     ts1))
         | STok T_RPAREN :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_LANGLE :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_RANGLE :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_LBRACE :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_RBRACE :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_COMMA :: _ -> Inl (expected (squote ['\040']) ts)
         | STok T_SEMICOLON :: _ -> Inl (expected (squote ['\040']) ts)
         | STok (T_STR _) :: _ -> Inl (expected (squote ['\040']) ts)
         | SErr :: _ -> Inl (expected (squote ['\040']) ts));;

let rec colon_parts
  s = (let a = takeWhile (fun c -> not (((c : char) = '\058'))) s in
       let r = dropWhile (fun c -> not (((c : char) = '\058'))) s in
        (if null r then [a] else a :: colon_parts (tla r)));;

let rec nsplit_colon s = (if null s then [] else colon_parts s);;

let rec get_type
  t = (if equal_lista equal_char t ['\105'; '\110'; '\116'] then Inr SInt
        else (if equal_lista equal_char t
                   ['\115'; '\116'; '\114'; '\105'; '\110'; '\103']
               then Inr SStr
               else (if equal_lista equal_char t
                          ['\102'; '\108'; '\111'; '\097'; '\116']
                      then Inr SFloat
                      else (if equal_lista equal_char t
                                 ['\114'; '\101'; '\103'; '\101'; '\120';
                                   '\112']
                             then Inr SRegexp
                             else Inl (SE_PARSE
(['\085'; '\110'; '\107'; '\110'; '\111'; '\119'; '\110'; '\032'; '\116';
   '\121'; '\112'; '\101'; '\032'] @
  t))))));;

let rec map_sum f1 f2 x2 = match f1, f2, x2 with f1, f2, Inl a -> Inl (f1 a)
                  | f1, f2, Inr a -> Inr (f2 a);;

let rec field_decl
  f = (match nsplit_colon f with [] -> Inl SE_INTERNAL
        | [t] -> map_sum id (fun a -> ([], a)) (get_type t)
        | t :: ta :: _ -> map_sum id (fun a -> (t, a)) (get_type ta));;

let rec field_decls
  = function [] -> Inr []
    | f :: fs ->
        (match field_decl f with Inl a -> Inl a
          | Inr d -> map_sum id (fun a -> d :: a) (field_decls fs));;

let rec add_decl
  d s = (match field_decls (snd d) with Inl a -> Inl a
          | Inr l ->
            (if member ((ceq_list ceq_char), (ccompare_list ccompare_char))
                  (fst d)
                  (image
                    ((ceq_prod (ceq_list ceq_char)
                       (ceq_list (ceq_prod (ceq_list ceq_char) ceq_sty))),
                      (ccompare_prod (ccompare_list ccompare_char)
                        (ccompare_list
                          (ccompare_prod (ccompare_list ccompare_char)
                            ccompare_sty))))
                    ((ceq_list ceq_char), (ccompare_list ccompare_char),
                      set_impl_list)
                    fst (set ((ceq_prod (ceq_list ceq_char)
                                (ceq_list
                                  (ceq_prod (ceq_list ceq_char) ceq_sty))),
                               (ccompare_prod (ccompare_list ccompare_char)
                                 (ccompare_list
                                   (ccompare_prod (ccompare_list ccompare_char)
                                     ccompare_sty))),
                               (set_impl_prod set_impl_list set_impl_list))
                          s))
              then Inl (SE_TWICE (fst d)) else Inr ((fst d, l) :: s)));;

let rec sig_decls
  x0 s = match x0, s with [], s -> Inr s
    | STok (T_STR p) :: ts, s ->
        (match sig_tuple ts with Inl a -> Inl a
          | Inr (fs, tsa) ->
            (match add_decl (p, fs) s with Inl a -> Inl a
              | Inr a -> sig_decls tsa a))
    | STok T_AT :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_AT :: va))
    | STok T_LPAREN :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_LPAREN :: va))
    | STok T_RPAREN :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_RPAREN :: va))
    | STok T_LANGLE :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_LANGLE :: va))
    | STok T_RANGLE :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_RANGLE :: va))
    | STok T_LBRACE :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_LBRACE :: va))
    | STok T_RBRACE :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_RBRACE :: va))
    | STok T_COMMA :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_COMMA :: va))
    | STok T_SEMICOLON :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (STok T_SEMICOLON :: va))
    | SErr :: va, s ->
        Inl (expected
              ['\097'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110'; '\103']
              (SErr :: va));;

let rec read_sig s = sig_decls (sig_tokens s) base_schema;;

