let rec opt_lookup
  k = map_option fst (map_of (equal_list equal_char) opt_table k);;

let rec digit7 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 7));;

let rec digit6 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 6));;

let rec digit5 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 5));;

let rec digit4 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 4));;

let rec digit3 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 3));;

let rec digit2 c = bit_integer ((Z.of_int (Char.code c))) (Nat (Z.of_int 2));;

let rec digit1 c = bit_integer ((Z.of_int (Char.code c))) one_nata;;

let rec digit0 c = bit_integer ((Z.of_int (Char.code c))) zero_nata;;

let rec case_char
  f c = f (digit0 c) (digit1 c) (digit2 c) (digit3 c) (digit4 c) (digit5 c)
          (digit6 c)
          (digit7 c);;

let rec is_int_arg
  s = (let d =
         (match s with [] -> s
           | a :: d ->
             case_char
               (fun bool1 bool2 bool3 bool4 bool5 bool6 bool7 bool8 ->
                 (match bool1
                   with true ->
                     (match bool2
                       with true ->
                         (match bool3 with true -> s
                           | false ->
                             (match bool4
                               with true ->
                                 (match bool5 with true -> s
                                   | false ->
                                     (match bool6
                                       with true ->
 (match bool7 with true -> s
   | false -> (match bool8 with true -> s | false -> d))
                                       | false -> s))
                               | false -> s))
                       | false ->
                         (match bool3
                           with true ->
                             (match bool4
                               with true ->
                                 (match bool5 with true -> s
                                   | false ->
                                     (match bool6
                                       with true ->
 (match bool7 with true -> s
   | false -> (match bool8 with true -> s | false -> d))
                                       | false -> s))
                               | false -> s)
                           | false -> s))
                   | false -> s))
               a)
         in
        not (null d) &&
          list_all (fun c -> (('\048' : char) <= c) && ((c : char) <= '\057'))
            d);;

let rec spec_line
  = function
    (k, (OSym l, d)) ->
      ['\032'; '\032'] @
        k @ ['\032'; '\123'] @ concat (between ['\124'] l) @ ['\125'] @ d @ nl
    | (k, (OFlag, d)) ->
        (if null d then [] else ['\032'; '\032'] @ k @ ['\032'] @ d @ nl)
    | (k, (OStr, d)) ->
        (if null d then [] else ['\032'; '\032'] @ k @ ['\032'] @ d @ nl)
    | (k, (OInt, d)) ->
