let rec ground = function Var x -> false
                 | Const c -> true
                 | Plus (t, u) -> ground t && ground u
                 | Minus (t, u) -> ground t && ground u
                 | UMinus t -> ground t
                 | Mult (t, u) -> ground t && ground u
                 | Div (t, u) -> ground t && ground u
                 | Mod (t, u) -> ground t && ground u
                 | F2i t -> ground t
                 | I2f t -> ground t;;

let rec uminus_event_data = function EInt x -> EInt (Z.neg x)
                            | EFloat x -> EFloat (Stdlib.(~-.) x)
                            | EString v -> failwith "undefined";;

let rec mod_to_zero
  x y = (let z =
           snd ((fun k l -> if Z.equal Z.zero l then (Z.zero, l) else Z.div_rem
                  (Z.abs k) (Z.abs l))
                 x y)
           in
          (if Z.lt x Z.zero then Z.neg z else z));;

let rec modulo_event_data
  uu uv = match uu, uv with EInt x, EInt y -> EInt (mod_to_zero x y)
    | EFloat v, uv -> failwith "undefined"
    | EString v, uv -> failwith "undefined"
    | uu, EFloat v -> failwith "undefined"
    | uu, EString v -> failwith "undefined";;

let rec div_to_zero
  x y = (let z =
           fst ((fun k l -> if Z.equal Z.zero l then (Z.zero, l) else Z.div_rem
                  (Z.abs k) (Z.abs l))
                 x y)
           in
          (if not (equal_boola (Z.lt x Z.zero) (Z.lt y Z.zero)) then Z.neg z
            else z));;

let rec divide_event_data
  uu uv = match uu, uv with EInt x, EInt y -> EInt (div_to_zero x y)
    | EFloat x, EFloat y -> EFloat (Stdlib.(/.) x y)
    | EFloat v, EInt va -> failwith "undefined"
    | EFloat v, EString va -> failwith "undefined"
    | EString v, uv -> failwith "undefined"
    | EInt va, EFloat v -> failwith "undefined"
    | uu, EString v -> failwith "undefined";;

let rec times_event_data
  uu uv = match uu, uv with EInt x, EInt y -> EInt (Z.mul x y)
    | EFloat x, EFloat y -> EFloat (Stdlib.( *. ) x y)
    | EFloat v, EInt va -> failwith "undefined"
    | EFloat v, EString va -> failwith "undefined"
    | EString v, uv -> failwith "undefined"
    | EInt va, EFloat v -> failwith "undefined"
    | uu, EString v -> failwith "undefined";;

let rec minus_event_data
  uu uv = match uu, uv with EInt x, EInt y -> EInt (Z.sub x y)
    | EFloat x, EFloat y -> EFloat (Stdlib.(-.) x y)
    | EFloat v, EInt va -> failwith "undefined"
    | EFloat v, EString va -> failwith "undefined"
    | EString v, uv -> failwith "undefined"
    | EInt va, EFloat v -> failwith "undefined"
    | uu, EString v -> failwith "undefined";;

let rec plus_event_data
  uu uv = match uu, uv with EInt x, EInt y -> EInt (Z.add x y)
    | EFloat x, EFloat y -> EFloat (Stdlib.(+.) x y)
    | EFloat v, EInt va -> failwith "undefined"
    | EFloat v, EString va -> failwith "undefined"
    | EString v, uv -> failwith "undefined"
    | EInt va, EFloat v -> failwith "undefined"
    | uu, EString v -> failwith "undefined";;

let rec integer_of_event_data = function EInt uu -> failwith "undefined"
                                | EFloat x -> Z.of_float x
                                | EString uv -> failwith "undefined";;

let rec double_of_event_data = function EInt x -> Z.to_float x
                               | EFloat uu -> failwith "undefined"
                               | EString uv -> failwith "undefined";;

let rec eval_trm
  v x1 = match v, x1 with v, Var x -> nth v x
    | v, Const x -> x
    | v, Plus (x, y) -> plus_event_data (eval_trm v x) (eval_trm v y)
    | v, Minus (x, y) -> minus_event_data (eval_trm v x) (eval_trm v y)
    | v, UMinus x -> uminus_event_data (eval_trm v x)
    | v, Mult (x, y) -> times_event_data (eval_trm v x) (eval_trm v y)
    | v, Div (x, y) -> divide_event_data (eval_trm v x) (eval_trm v y)
    | v, Mod (x, y) -> modulo_event_data (eval_trm v x) (eval_trm v y)
    | v, F2i x -> EInt (integer_of_event_data (eval_trm v x))
    | v, I2f x -> EFloat (double_of_event_data (eval_trm v x));;

let rec fold_trm t = (if ground t then Const (eval_trm [] t) else t);;

let rec map_regex
  f x1 = match f, x1 with f, Skip x1 -> Skip x1
    | f, Test x2 -> Test (f x2)
    | f, Plusa (x31, x32) -> Plusa (map_regex f x31, map_regex f x32)
    | f, Times (x41, x42) -> Times (map_regex f x41, map_regex f x42)
    | f, Star x5 -> Star (map_regex f x5);;

let rec fold_ground
  = function Pred (p, ts) -> Pred (p, mapa fold_trm ts)
    | Let (p, f, g) -> Let (p, fold_ground f, fold_ground g)
    | Frz (p, f, g) -> Frz (p, fold_ground f, fold_ground g)
    | LetPast (p, f, g) -> LetPast (p, fold_ground f, fold_ground g)
    | Eq (t, u) -> Eq (fold_trm t, fold_trm u)
    | Less (t, u) -> Less (fold_trm t, fold_trm u)
    | LessEq (t, u) -> LessEq (fold_trm t, fold_trm u)
    | Neg f -> Neg (fold_ground f)
    | Or (f, g) -> Or (fold_ground f, fold_ground g)
    | And (f, g) -> And (fold_ground f, fold_ground g)
    | Ands fs -> Ands (mapa fold_ground fs)
    | Exists (t, f) -> Exists (t, fold_ground f)
    | Agg (y, omega, b, u, f) -> Agg (y, omega, b, u, fold_ground f)
    | Prev (i, f) -> Prev (i, fold_ground f)
    | Next (i, f) -> Next (i, fold_ground f)
    | Since (f, i, g) -> Since (fold_ground f, i, fold_ground g)
    | Until (f, i, g) -> Until (fold_ground f, i, fold_ground g)
    | Trigger (f, i, g) -> Trigger (fold_ground f, i, fold_ground g)
    | Release (f, i, g) -> Release (fold_ground f, i, fold_ground g)
    | MatchF (i, r) -> MatchF (i, map_regex fold_ground r)
    | MatchP (i, r) -> MatchP (i, map_regex fold_ground r)
    | TP t -> TP (fold_trm t)
    | TS t -> TS (fold_trm t);;

let rec mp_union _A xs ys = xs @ filtera (fun y -> not (membera _A xs y)) ys;;

let rec remdups _A
  = function [] -> []
    | x :: xs ->
        (if membera _A xs x then remdups _A xs else x :: remdups _A xs);;

let rec dedup _A xs = rev (remdups _A (rev xs));;

let rec mp_pvars p = dedup (equal_list equal_char) (pvars p);;

let rec mp_fv
  = function
    FEqual (t, u) -> mp_union (equal_list equal_char) (tvars t) (tvars u)
    | FLess (t, u) -> mp_union (equal_list equal_char) (tvars t) (tvars u)
    | FLessEq (t, u) -> mp_union (equal_list equal_char) (tvars t) (tvars u)
    | FSubstring (t, u) -> mp_union (equal_list equal_char) (tvars t) (tvars u)
    | FMatches (t, u, ts) ->
        fold (fun ta s ->
               (match ta with None -> s
                 | Some tb -> mp_union (equal_list equal_char) s (tvars tb)))
          ts (mp_union (equal_list equal_char) (tvars t) (tvars u))
    | FPred p -> mp_pvars p
    | FLet (uu, uv, g) -> mp_fv g
    | FLetPast (uw, ux, g) -> mp_fv g
    | FFrz (uy, uz, g) -> mp_fv g
    | FNeg f -> mp_fv f
    | FAnd (f, g) -> mp_union (equal_list equal_char) (mp_fv f) (mp_fv g)
    | FOr (f, g) -> mp_union (equal_list equal_char) (mp_fv f) (mp_fv g)
    | FImplies (f, g) -> mp_union (equal_list equal_char) (mp_fv f) (mp_fv g)
    | FEquiv (f, g) -> mp_union (equal_list equal_char) (mp_fv f) (mp_fv g)
    | FExists (vs, f) ->
        filtera (fun v -> not (membera (equal_list equal_char) vs v)) (mp_fv f)
    | FForAll (vs, f) ->
        filtera (fun v -> not (membera (equal_list equal_char) vs v)) (mp_fv f)
    | FAggreg (y, va, vb, g, vc) -> y :: g
    | FPrev (vd, f) -> mp_fv f
    | FNext (ve, f) -> mp_fv f
    | FEventually (vf, f) -> mp_fv f
    | FOnce (vg, f) -> mp_fv f
    | FAlways (vh, f) -> mp_fv f
    | FPastAlways (vi, f) -> mp_fv f
    | FSince (vj, f, g) -> mp_union (equal_list equal_char) (mp_fv g) (mp_fv f)
    | FTrigger (vk, f, g) ->
        mp_union (equal_list equal_char) (mp_fv g) (mp_fv f)
    | FUntil (vl, f, g) -> mp_union (equal_list equal_char) (mp_fv g) (mp_fv f)
    | FRelease (vm, f, g) ->
        mp_union (equal_list equal_char) (mp_fv g) (mp_fv f)
    | FFrex (vn, r) -> mp_fv_r r
    | FPrex (vo, r) -> mp_fv_r r
and mp_fv_r
  = function RSkip vp -> []
    | RTest f -> mp_fv f
    | RConcat (r, s) -> mp_union (equal_list equal_char) (mp_fv_r r) (mp_fv_r s)
    | RPlus (r, s) -> mp_union (equal_list equal_char) (mp_fv_r r) (mp_fv_r s)
    | RStar r -> mp_fv_r r;;

let rec ex_used
  vs f =
    (let vsa = filtera (membera (equal_list equal_char) (mp_fv f)) vs in
      (if null vsa then f else FExists (vsa, f)));;

let ffalse : formulab
  = FNeg (FEqual (TCsta (CStr ['\120']), TCsta (CStr ['\120'])));;

let rec elim_sugar
  = function FLet (p, f, g) -> FLet (p, elim_sugar f, elim_sugar g)
    | FLetPast (p, f, g) -> FLetPast (p, elim_sugar f, elim_sugar g)
    | FFrz (p, f, g) -> FFrz (p, elim_sugar f, elim_sugar g)
    | FNeg f -> FNeg (elim_sugar f)
    | FAnd (f, g) -> FAnd (elim_sugar f, elim_sugar g)
    | FOr (f, g) -> FOr (elim_sugar f, elim_sugar g)
    | FExists (vs, f) -> ex_used vs (elim_sugar f)
    | FImplies (f, g) -> FOr (FNeg (elim_sugar f), elim_sugar g)
    | FEquiv (f, g) ->
        FAnd (FOr (FNeg (elim_sugar f), elim_sugar g),
               FOr (elim_sugar f, FNeg (elim_sugar g)))
    | FForAll (vs, f) -> FNeg (ex_used vs (FNeg (elim_sugar f)))
    | FAggreg (y, op, x, g, f) -> FAggreg (y, op, x, g, elim_sugar f)
    | FPrev (i, f) -> FPrev (i, elim_sugar f)
    | FNext (i, f) -> FNext (i, elim_sugar f)
    | FEventually (i, f) -> FEventually (i, elim_sugar f)
    | FOnce (i, f) -> FOnce (i, elim_sugar f)
    | FAlways (i, f) -> FRelease (i, ffalse, elim_sugar f)
    | FPastAlways (i, f) -> FTrigger (i, ffalse, elim_sugar f)
    | FSince (i, f, g) -> FSince (i, elim_sugar f, elim_sugar g)
    | FUntil (i, f, g) -> FUntil (i, elim_sugar f, elim_sugar g)
    | FTrigger (i, f, g) -> FTrigger (i, elim_sugar f, elim_sugar g)
    | FRelease (i, f, g) -> FRelease (i, elim_sugar f, elim_sugar g)
    | FFrex (i, r) -> FFrex (i, elim_sugar_r r)
    | FPrex (i, r) -> FPrex (i, elim_sugar_r r)
    | FEqual (v, va) -> FEqual (v, va)
    | FLess (v, va) -> FLess (v, va)
    | FLessEq (v, va) -> FLessEq (v, va)
    | FSubstring (v, va) -> FSubstring (v, va)
    | FMatches (v, va, vb) -> FMatches (v, va, vb)
    | FPred v -> FPred v
and elim_sugar_r
  = function RTest f -> RTest (elim_sugar f)
    | RConcat (r, s) -> RConcat (elim_sugar_r r, elim_sugar_r s)
    | RPlus (r, s) -> RPlus (elim_sugar_r r, elim_sugar_r s)
    | RStar r -> RStar (elim_sugar_r r)
    | RSkip v -> RSkip v;;

let rec out_vars f = dedup (equal_list equal_char) (mp_fv f);;

let rec string_of_int
  i = (if less_int i zero_int then '\045' :: digits_of_nat (nat (uminus_int i))
        else digits_of_nat (nat i));;

let rec string_of_cst = function CInt i -> string_of_int i
                        | CStr s -> '\034' :: s @ ['\034']
                        | CFloat s -> s
                        | CRegexp s -> '\114' :: '\034' :: s @ ['\034'];;

let rec paren b s = (if b then s else ['\040'] @ s @ ['\041']);;

let rec t2s
  x0 b = match x0, b with TVar v, b -> v
    | TCsta c, b -> string_of_cst c
    | TF2i u, b ->
        paren b (['\102'; '\050'; '\105'; '\040'] @ t2s u true @ ['\041'])
    | TI2f u, b ->
        paren b (['\105'; '\050'; '\102'; '\040'] @ t2s u true @ ['\041'])
    | TI2s u, b ->
        paren b (['\105'; '\050'; '\115'; '\040'] @ t2s u true @ ['\041'])
    | TS2i u, b ->
        paren b (['\115'; '\050'; '\105'; '\040'] @ t2s u true @ ['\041'])
    | TF2s u, b ->
        paren b (['\102'; '\050'; '\115'; '\040'] @ t2s u true @ ['\041'])
    | TS2f u, b ->
        paren b (['\115'; '\050'; '\102'; '\040'] @ t2s u true @ ['\041'])
    | TDayOfMonth u, b ->
        paren b
          (['\068'; '\065'; '\089'; '\095'; '\079'; '\070'; '\095'; '\077';
             '\079'; '\078'; '\084'; '\072'; '\040'] @
            t2s u true @ ['\041'])
    | TMonth u, b ->
        paren b
          (['\077'; '\079'; '\078'; '\084'; '\072'; '\040'] @
            t2s u true @ ['\041'])
    | TYear u, b ->
        paren b
          (['\089'; '\069'; '\065'; '\082'; '\040'] @ t2s u true @ ['\041'])
    | TFormatDate u, b ->
        paren b
          (['\070'; '\079'; '\082'; '\077'; '\065'; '\084'; '\095'; '\068';
             '\065'; '\084'; '\069'; '\040'] @
            t2s u true @ ['\041'])
    | TR2s u, b ->
        paren b (['\114'; '\050'; '\115'; '\040'] @ t2s u true @ ['\041'])
    | TS2r u, b ->
        paren b (['\115'; '\050'; '\114'; '\040'] @ t2s u true @ ['\041'])
    | TPlus (u, v), b ->
        paren b (t2s u false @ ['\032'; '\043'; '\032'] @ t2s v false)
    | TMinus (u, v), b ->
        paren b (t2s u false @ ['\032'; '\045'; '\032'] @ t2s v false)
    | TUMinus u, b -> paren b (['\045'] @ t2s u false)
    | TMult (u, v), b ->
        paren b (t2s u false @ ['\032'; '\042'; '\032'] @ t2s v false)
    | TDiv (u, v), b ->
        paren b (t2s u false @ ['\032'; '\047'; '\032'] @ t2s v false)
    | TMod (u, v), b ->
        paren b
          (t2s u false @
            ['\032'; '\109'; '\111'; '\100'; '\032'] @ t2s v false);;

let rec string_of_term t = t2s t true;;

let rec string_of_opt_term
  t = (match t with None -> ['\095'] | Some a -> string_of_term a);;

let rec between_list s x1 = match s, x1 with s, [] -> []
                       | s, [x] -> [x]
                       | s, x :: y :: zs -> x :: s :: between_list s (y :: zs);;

let rec conv_agg_op = function ACnt -> Agg_Cnt
                      | AMin -> Agg_Min
                      | AMax -> Agg_Max
                      | ASum -> Agg_Sum
                      | AAvg -> Agg_Avg
                      | AMed -> Agg_Med;;

let rec fresh_ty k = Inr (TAny k, suc k);;

let rec cbind m f k = (match m k with Inl a -> Inl a | Inr (a, b) -> f a b);;

let rec cret a k = Inr (a, k);;

let rec fresh_tys
  n = (if equal_nata n zero_nata then cret []
        else cbind fresh_ty
               (fun t ->
                 cbind (fresh_tys (minus_nata n one_nata))
                   (fun ts -> cret (t :: ts))));;

let special_preds : (char list) list
  = [['\116'; '\112']; ['\116'; '\115']; ['\116'; '\112'; '\116'; '\115']];;

let rec conv_cst
  pf x1 = match pf, x1 with pf, CInt i -> Inr (EInt (integer_of_int i))
    | pf, CStr s -> Inr (EString ((fun cs -> String.of_seq (List.to_seq cs)) s))
    | pf, CFloat s ->
        (match pf ((fun cs -> String.of_seq (List.to_seq cs)) s)
          with None ->
            Inl (unsupported
                  (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111';
                     '\114'; '\116'; '\101'; '\100'; '\032'; '\102'; '\108';
                     '\111'; '\097'; '\116'; '\032'; '\099'; '\111'; '\110';
                     '\115'; '\116'; '\097'; '\110'; '\116'; '\032'] @
                    s))
          | Some d -> Inr (EFloat d))
    | pf, CRegexp s ->
        Inl (unsupported
              ['\082'; '\101'; '\103'; '\117'; '\108'; '\097'; '\114'; '\032';
                '\101'; '\120'; '\112'; '\114'; '\101'; '\115'; '\115'; '\105';
                '\111'; '\110'; '\032'; '\099'; '\111'; '\110'; '\115'; '\116';
                '\097'; '\110'; '\116'; '\032'; '\097'; '\114'; '\101'; '\032';
                '\110'; '\111'; '\116'; '\032'; '\115'; '\117'; '\112'; '\112';
                '\111'; '\114'; '\116'; '\101'; '\100']);;

let rec pos_of _A xs a = size_lista (takeWhile (fun x -> not (eq _A x a)) xs);;

let rec var_idx
  fvl bvl a =
    (if membera (equal_list equal_char) bvl a
      then pos_of (equal_list equal_char) bvl a
      else plus_nata (size_lista bvl) (pos_of (equal_list equal_char) fvl a));;

let rec conv_trm
  pf fvl bvl x3 = match pf, fvl, bvl, x3 with
    pf, fvl, bvl, TVar a -> Inr (Var (var_idx fvl bvl a))
    | pf, fvl, bvl, TCsta c -> map_sum id (fun a -> Const a) (conv_cst pf c)
    | pf, fvl, bvl, TF2i t ->
        map_sum id (fun a -> F2i a) (conv_trm pf fvl bvl t)
    | pf, fvl, bvl, TI2f t ->
        map_sum id (fun a -> I2f a) (conv_trm pf fvl bvl t)
    | pf, fvl, bvl, TUMinus t ->
        map_sum id (fun a -> UMinus a) (conv_trm pf fvl bvl t)
    | pf, fvl, bvl, TPlus (t, u) ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> Plus (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, TMinus (t, u) ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> Minus (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, TMult (t, u) ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> Mult (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, TDiv (t, u) ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> Div (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, TMod (t, u) ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> Mod (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, TI2s v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TI2s v)))
    | pf, fvl, bvl, TS2i v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TS2i v)))
    | pf, fvl, bvl, TF2s v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TF2s v)))
    | pf, fvl, bvl, TS2f v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TS2f v)))
    | pf, fvl, bvl, TDayOfMonth v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TDayOfMonth v)))
    | pf, fvl, bvl, TMonth v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TMonth v)))
    | pf, fvl, bvl, TYear v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TYear v)))
    | pf, fvl, bvl, TFormatDate v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TFormatDate v)))
    | pf, fvl, bvl, TR2s v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TR2s v)))
    | pf, fvl, bvl, TS2r v ->
        Inl (unsupported
              (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                 '\116'; '\101'; '\100'; '\032'; '\116'; '\101'; '\114'; '\109';
                 '\032'] @
                string_of_term (TS2r v)));;

let rec conv_trms
  pf fvl bvl x3 = match pf, fvl, bvl, x3 with pf, fvl, bvl, [] -> Inr []
    | pf, fvl, bvl, t :: ts ->
        (match conv_trm pf fvl bvl t with Inl a -> Inl a
          | Inr a -> map_sum id (fun b -> a :: b) (conv_trms pf fvl bvl ts));;

