let rec string_of_bound_r = function OBnd a -> string_of_int a @ ['\041']
                            | CBnd a -> string_of_int a @ ['\093']
                            | BInf -> ['\042'; '\041'];;

let rec string_of_bound_l
  = function OBnd a -> ['\040'] @ string_of_int a @ ['\044']
    | CBnd a -> ['\091'] @ string_of_int a @ ['\044']
    | BInf -> ['\040'; '\042'; '\044'];;

let rec string_of_interval
  i = string_of_bound_l (fst i) @ string_of_bound_r (snd i);;

let rec interval
  xb xc =
    Abs_I (if less_eq_enat (Enat xb) xc
            then (less_eq_nat xb,
                   ((fun i -> less_eq_enat (Enat i) xc),
                     not (equal_enat xc Infinity_enat)))
            else ((fun _ -> true), ((fun _ -> true), false)));;

let rec conv_intv
  i = (let err =
         Inl (unsupported
               (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111'; '\114';
                  '\116'; '\101'; '\100'; '\032'; '\105'; '\110'; '\116';
                  '\101'; '\114'; '\118'; '\097'; '\108'; '\032'] @
                 string_of_interval i))
         in
        (match fst i
          with OBnd _ ->
            (let l =
               (match fst i with OBnd a -> plus_int a one_int | CBnd a -> a
                 | BInf -> zero_int)
               in
              (match snd i
                with OBnd int ->
                  (let r =
                     (match OBnd int with OBnd a -> minus_int a one_int
                       | CBnd a -> a | BInf -> zero_int)
                     in
                    (if less_eq_int l r
                      then Inr (interval (nat l) (Enat (nat r))) else err))
                | CBnd int ->
                  (let r =
                     (match CBnd int with OBnd a -> minus_int a one_int
                       | CBnd a -> a | BInf -> zero_int)
                     in
                    (if less_eq_int l r
                      then Inr (interval (nat l) (Enat (nat r))) else err))
                | BInf -> Inr (interval (nat l) Infinity_enat)))
          | CBnd _ ->
            (let l =
               (match fst i with OBnd a -> plus_int a one_int | CBnd a -> a
                 | BInf -> zero_int)
               in
              (match snd i
                with OBnd int ->
                  (let r =
                     (match OBnd int with OBnd a -> minus_int a one_int
                       | CBnd a -> a | BInf -> zero_int)
                     in
                    (if less_eq_int l r
                      then Inr (interval (nat l) (Enat (nat r))) else err))
                | CBnd int ->
                  (let r =
                     (match CBnd int with OBnd a -> minus_int a one_int
                       | CBnd a -> a | BInf -> zero_int)
                     in
                    (if less_eq_int l r
                      then Inr (interval (nat l) (Enat (nat r))) else err))
                | BInf -> Inr (interval (nat l) Infinity_enat)))
          | BInf -> err));;

let rec def_vars p = maps tvars (snd p);;

let rec ex_wrap
  n f = (if equal_nata n zero_nata then cret f
          else cbind fresh_ty
                 (fun t -> ex_wrap (minus_nata n one_nata) (Exists (t, f))));;

let truth : tysym formula = Eq (Const (EInt Z.zero), Const (EInt Z.zero));;

let rec clift x k = map_sum id (fun a -> (a, k)) x;;

let rec conv_f
  pf fvl bvl lets x4 = match pf, fvl, bvl, lets, x4 with
    pf, fvl, bvl, lets, FEqual (t, u) ->
      clift (match conv_trm pf fvl bvl t with Inl a -> Inl a
              | Inr a ->
                map_sum id (fun b -> Eq (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, lets, FLess (t, u) ->
        clift (match conv_trm pf fvl bvl t with Inl a -> Inl a
                | Inr a ->
                  map_sum id (fun b -> Less (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, lets, FLessEq (t, u) ->
        clift (match conv_trm pf fvl bvl t with Inl a -> Inl a
                | Inr a ->
                  map_sum id (fun b -> LessEq (a, b)) (conv_trm pf fvl bvl u))
    | pf, fvl, bvl, lets, FSubstring (t, u) ->
        clift (Inl (unsupported
                     (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111';
                        '\114'; '\116'; '\101'; '\100'; '\032'; '\102'; '\111';
                        '\114'; '\109'; '\117'; '\108'; '\097'; '\032'] @
                       string_of_term t @
                         ['\032'; '\083'; '\085'; '\066'; '\083'; '\084';
                           '\082'; '\073'; '\078'; '\071'; '\032'] @
                           string_of_term u)))
    | pf, fvl, bvl, lets, FMatches (t, u, ts) ->
        clift (Inl (unsupported
                     (['\085'; '\110'; '\115'; '\117'; '\112'; '\112'; '\111';
                        '\114'; '\116'; '\101'; '\100'; '\032'; '\102'; '\111';
                        '\114'; '\109'; '\117'; '\108'; '\097'; '\032'] @
                       string_of_term t @
                         ['\032'; '\077'; '\065'; '\084'; '\067'; '\072';
                           '\069'; '\083'; '\032'] @
                           string_of_term u @
                             (if null ts then []
                               else ['\032'; '\040'] @
                                      concat
(between_list ['\044'; '\032'] (mapa string_of_opt_term ts)) @
['\041']))))
    | pf, fvl, bvl, lets, FPred p -> clift (conv_pred pf fvl bvl lets p)
    | pf, fvl, bvl, lets, FLet (p, f, g) ->
        cbind (conv_f pf (def_vars p) [] lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl ((fst p, size_lista (snd p)) :: lets) g)
              (fun b ->
                cret (Let ((fun cs -> String.of_seq (List.to_seq cs)) (fst p),
                            a, b))))
    | pf, fvl, bvl, lets, FLetPast (p, f, g) ->
        cbind (conv_f pf (def_vars p) [] ((fst p, size_lista (snd p)) :: lets)
                f)
          (fun a ->
            cbind (conv_f pf fvl bvl ((fst p, size_lista (snd p)) :: lets) g)
              (fun b ->
                cret (LetPast
                       ((fun cs -> String.of_seq (List.to_seq cs)) (fst p), a,
                         b))))
    | pf, fvl, bvl, lets, FFrz (p, f, g) ->
        cbind (conv_f pf (def_vars p) [] lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl ((fst p, size_lista (snd p)) :: lets) g)
              (fun b ->
                cret (Frz ((fun cs -> String.of_seq (List.to_seq cs)) (fst p),
                            a, b))))
    | pf, fvl, bvl, lets, FNeg f ->
        cbind (conv_f pf fvl bvl lets f) (fun a -> cret (Neg a))
    | pf, fvl, bvl, lets, FAnd (f, g) ->
        cbind (conv_f pf fvl bvl lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl lets g) (fun b -> cret (And (a, b))))
    | pf, fvl, bvl, lets, FOr (f, g) ->
        cbind (conv_f pf fvl bvl lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl lets g) (fun b -> cret (Or (a, b))))
    | pf, fvl, bvl, lets, FImplies (f, g) ->
        cbind (conv_f pf fvl bvl lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl lets g) (fun b -> cret (Or (Neg a, b))))
    | pf, fvl, bvl, lets, FEquiv (f, g) ->
        cbind (conv_f pf fvl bvl lets f)
          (fun a ->
            cbind (conv_f pf fvl bvl lets g)
              (fun b -> cret (And (Or (Neg a, b), Or (Neg b, a)))))
    | pf, fvl, bvl, lets, FExists (vs, f) ->
        cbind (conv_f pf fvl (vs @ bvl) lets f) (ex_wrap (size_lista vs))
    | pf, fvl, bvl, lets, FForAll (vs, f) ->
        cbind (conv_f pf fvl (vs @ bvl) lets f)
          (fun a ->
            cbind (ex_wrap (size_lista vs) (Neg a)) (fun b -> cret (Neg b)))
    | pf, fvl, bvl, lets, FAggreg (y, op, x, g, f) ->
        (let bound =
           filtera (fun v -> not (membera (equal_list equal_char) g v))
             (dedup (equal_list equal_char) (mp_fv f))
           in
          cbind fresh_ty
            (fun t ->
              cbind (fresh_tys (size_lista bound))
                (fun ts ->
                  cbind (clift (conv_trm pf fvl (bound @ bvl) (TVar x)))
                    (fun u ->
                      cbind (conv_f pf fvl (bound @ bvl) lets f)
                        (fun a ->
                          cret (Agg (var_idx fvl bvl y, (conv_agg_op op, t), ts,
                                      u, a)))))))
    | pf, fvl, bvl, lets, FPrev (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f) (fun a -> cret (Prev (ia, a))))
    | pf, fvl, bvl, lets, FNext (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f) (fun a -> cret (Next (ia, a))))
    | pf, fvl, bvl, lets, FEventually (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a -> cret (Until (truth, ia, a))))
    | pf, fvl, bvl, lets, FOnce (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a -> cret (Since (truth, ia, a))))
    | pf, fvl, bvl, lets, FAlways (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a -> cret (Neg (Until (truth, ia, Neg a)))))
    | pf, fvl, bvl, lets, FPastAlways (i, f) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a -> cret (Neg (Since (truth, ia, Neg a)))))
    | pf, fvl, bvl, lets, FSince (i, f, g) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a ->
                cbind (conv_f pf fvl bvl lets g)
                  (fun b -> cret (Since (a, ia, b)))))
    | pf, fvl, bvl, lets, FTrigger (i, f, g) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a ->
                cbind (conv_f pf fvl bvl lets g)
                  (fun b -> cret (Trigger (a, ia, b)))))
    | pf, fvl, bvl, lets, FUntil (i, f, g) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a ->
                cbind (conv_f pf fvl bvl lets g)
                  (fun b -> cret (Until (a, ia, b)))))
    | pf, fvl, bvl, lets, FRelease (i, f, g) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_f pf fvl bvl lets f)
              (fun a ->
                cbind (conv_f pf fvl bvl lets g)
                  (fun b -> cret (Release (a, ia, b)))))
    | pf, fvl, bvl, lets, FFrex (i, r) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_r pf fvl bvl lets r) (fun a -> cret (MatchF (ia, a))))
    | pf, fvl, bvl, lets, FPrex (i, r) ->
        cbind (clift (conv_intv i))
          (fun ia ->
            cbind (conv_r pf fvl bvl lets r) (fun a -> cret (MatchP (ia, a))))
and conv_r
  pf fvl bvl lets x4 = match pf, fvl, bvl, lets, x4 with
    pf, fvl, bvl, lets, RSkip n -> cret (Skip n)
    | pf, fvl, bvl, lets, RTest f ->
        cbind (conv_f pf fvl bvl lets f) (fun a -> cret (Test a))
    | pf, fvl, bvl, lets, RConcat (r, s) ->
        cbind (conv_r pf fvl bvl lets r)
          (fun a ->
            cbind (conv_r pf fvl bvl lets s) (fun b -> cret (Times (a, b))))
    | pf, fvl, bvl, lets, RPlus (r, s) ->
        cbind (conv_r pf fvl bvl lets r)
          (fun a ->
            cbind (conv_r pf fvl bvl lets s) (fun b -> cret (Plusa (a, b))))
    | pf, fvl, bvl, lets, RStar r ->
        cbind (conv_r pf fvl bvl lets r) (fun a -> cret (Star a));;

let rec conv_formula
  pf rw f =
    (let fvl = out_vars f in
      map_sum id (fun (phi, _) -> (if rw then fold_ground phi else phi))
        (conv_f pf fvl [] [] (if rw then elim_sugar f else f)
          (size_lista fvl)));;

