          | (Var _, UMinus _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var _, Mult (_, _)) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var _, Div (_, _)) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var _, Mod (_, _)) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var _, F2i _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var _, I2f _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Const _, _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Plus (_, _), _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Minus (_, _), _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (UMinus _, _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Mult (_, _), _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Div (_, _), _) ->
