          | (F2i _, _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (I2f _, _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata))
    | b, LessEqa (t1, t2) ->
        (match (t1, t2)
          with (Var _, Var _) ->
            set_empty (ceq_nat, ccompare_nat) (of_phantom set_impl_nata)
          | (Var x, Const _) ->
            insert (ceq_nat, ccompare_nat) (minus_nata x b)
