let rec is_future = function FNeg f -> is_future f
                    | FExists (uu, f) -> is_future f
                    | FForAll (uv, f) -> is_future f
                    | FAggreg (uw, ux, uy, uz, f) -> is_future f
                    | FPrev (va, f) -> is_future f
                    | FOnce (vb, f) -> is_future f
                    | FPastAlways (vc, f) -> is_future f
                    | FPrex (vd, r) -> is_future_r r
                    | FAnd (f, g) -> is_future f || is_future g
                    | FOr (f, g) -> is_future f || is_future g
                    | FImplies (f, g) -> is_future f || is_future g
                    | FEquiv (f, g) -> is_future f || is_future g
                    | FSince (ve, f, g) -> is_future f || is_future g
                    | FTrigger (vf, f, g) -> is_future f || is_future g
                    | FLet (vg, f, g) -> is_future f || is_future g
                    | FLetPast (vh, f, g) -> is_future f || is_future g
                    | FFrz (vi, f, g) -> is_future f || is_future g
                    | FNext (vj, vk) -> true
                    | FEventually (vl, vm) -> true
                    | FAlways (vn, vo) -> true
                    | FUntil (vp, vq, vr) -> true
                    | FRelease (vs, vt, vu) -> true
                    | FFrex (vv, vw) -> true
                    | FEqual (v, va) -> false
                    | FLess (v, va) -> false
                    | FLessEq (v, va) -> false
                    | FSubstring (v, va) -> false
                    | FMatches (v, va, vb) -> false
                    | FPred v -> false
and is_future_r = function RTest f -> is_future f
                  | RConcat (r, s) -> is_future_r r || is_future_r s
                  | RPlus (r, s) -> is_future_r r || is_future_r s
                  | RStar r -> is_future_r r
                  | RSkip vy -> false;;

let rec prep_msg
  e = [id "Fatal error: exception Failure(\034Error during the verified preparation of the formula: ";
        id e; id "\034)"; id "\010"];;

let rec start_monitor
  conf pf psi s =
    (match input_error s psi
      with None ->
        (match conv_formula pf (c_rw conf) psi
          with Inl msg -> Done ([], otxt (msg @ nl), Nat (Z.of_int 2))
          | Inr phi ->
            (match lsig_of s phi
              with Inl msg -> Done ([], otxt (msg @ nl), Nat (Z.of_int 2))
              | Inr l ->
                (let vs = out_vars psi in
                 let info = c_verbose conf || c_check conf in
                  (match check (lsig_tsig l) (fun a -> TAny a) phi
                    with Inl e -> Done ([], prep_msg e, Nat (Z.of_int 2))
                    | Inr f ->
                      (match
                        vinit (c_index conf) (c_mw conf) (c_rw conf)
                          (c_filter conf) l pf phi
                        with Inl VI_WF ->
                          Done ([], prep_msg "the formula is not well-formed",
                                 Nat (Z.of_int 2))
                        | Inl (VI_PREPARE e) ->
                          (let msg =
                             (if info
                               then otxt (fv_text vs) @
                                      [(if c_rw conf
 then id "The analyzed formula is NOT monitorable: "
 else id "The formula is NOT monitorable: ");
id e; id "\010"]
                               else otxt (['\084'; '\104'; '\101'; '\032';
    '\102'; '\111'; '\114'; '\109'; '\117'; '\108'; '\097'; '\032'; '\105';
    '\115'; '\032'; '\078'; '\079'; '\084'; '\032'; '\109'; '\111'; '\110';
    '\105'; '\116'; '\111'; '\114'; '\097'; '\098'; '\108'; '\101'; '\046';
    '\032'; '\085'; '\115'; '\101'; '\032'; '\116'; '\104'; '\101'; '\032';
    '\045'; '\099'; '\104'; '\101'; '\099'; '\107'; '\032'; '\111'; '\114';
    '\032'; '\045'; '\118'; '\101'; '\114'; '\098'; '\111'; '\115'; '\101';
    '\032'; '\102'; '\108'; '\097'; '\103'; '\115'; '\046'] @
   nl))
                             in
                            (if c_sigout conf
                              then Done (otxt (sigout_text vs f), msg,
  zero_nata)
                              else Done ([], msg, zero_nata)))
                        | Inl (VI_FRAGMENT _) ->
                          Done ([], otxt (fatal_failure
    ['\116'; '\104'; '\101'; '\032'; '\102'; '\111'; '\114'; '\109'; '\117';
      '\108'; '\097'; '\032'; '\105'; '\115'; '\032'; '\111'; '\117'; '\116';
      '\115'; '\105'; '\100'; '\101'; '\032'; '\116'; '\104'; '\101'; '\032';
      '\118'; '\101'; '\114'; '\105'; '\102'; '\105'; '\101'; '\100'; '\032';
      '\100'; '\101'; '\110'; '\115'; '\101'; '\032'; '\102'; '\114'; '\097';
      '\103'; '\109'; '\101'; '\110'; '\116'] @
   nl),
                                 Nat (Z.of_int 2))
                        | Inr (cf, z) ->
                          (let msg =
                             otxt ((if info then fv_text vs else []) @
                                    (if c_rw conf
                                      then (if c_check conf
     then ['\084'; '\104'; '\101'; '\032'; '\097'; '\110'; '\097'; '\108';
            '\121'; '\122'; '\101'; '\100'; '\032'; '\102'; '\111'; '\114';
            '\109'; '\117'; '\108'; '\097'; '\032'; '\105'; '\115'; '\032';
            '\109'; '\111'; '\110'; '\105'; '\116'; '\111'; '\114'; '\097';
            '\098'; '\108'; '\101'; '\046'] @
            nl
     else [])
                                      else (if info
     then ['\084'; '\104'; '\101'; '\032'; '\102'; '\111'; '\114'; '\109';
            '\117'; '\108'; '\097'; '\032'; '\105'; '\115'; '\032'; '\109';
            '\111'; '\110'; '\105'; '\116'; '\111'; '\114'; '\097'; '\098';
            '\108'; '\101'; '\046'] @
            nl
     else [])))
                             in
                            (if c_sigout conf
                              then Done (otxt (sigout_text vs f), msg,
  zero_nata)
                              else (if c_check conf
                                     then Done ([], msg, zero_nata)
                                     else Run
    (msg, conf, cf, z,
      (if c_newlastts conf && is_future psi then Some ts_max else None),
      size_lista vs, l)))))))))
      | Some e -> Done ([], otxt (fatal_failure e @ nl), Nat (Z.of_int 2)));;

let rec c_negate
  (Config_ext
    (c_sig, c_formula, c_log, c_negate, c_verbose, c_check, c_rw, c_mw, c_index,
      c_sigout, c_unix, c_mem, c_newlastts, c_filter, c_ignore_errors,
      c_stop_first, c_version, c_gc_space_overhead, c_gc_minor_heap, more))
    = c_negate;;

let rec input_formula conf psi = (if c_negate conf then FNeg psi else psi);;

let rec cli_main
  prog args pf =
    (match parse_command (string_of_bytes prog) (mapa string_of_bytes args)
      with CRun conf ->
        (if c_version conf then Version
          else (if null (c_formula conf)
                 then Done ([], otxt (usage_string @ nl), Nat (Z.of_int 2))
                 else NeedFile
                        ((fun cs -> String.of_seq (List.to_seq cs))
                           (c_formula conf),
                          (fun ftext ->
                            (match parse_formula (string_of_bytes ftext)
                              with None ->
                                Done ([], otxt
    (['\091'; '\077'; '\097'; '\105'; '\110'; '\046'; '\109'; '\097'; '\105';
       '\110'; '\093'; '\032'; '\070'; '\097'; '\105'; '\108'; '\101'; '\100';
       '\032'; '\116'; '\111'; '\032'; '\112'; '\097'; '\114'; '\115'; '\101';
       '\032'; '\102'; '\111'; '\114'; '\109'; '\117'; '\108'; '\097'; '\032';
       '\102'; '\105'; '\108'; '\101'] @
      nl @ fatal_failure
             ['\091'; '\077'; '\097'; '\105'; '\110'; '\046'; '\109'; '\097';
               '\105'; '\110'; '\093'; '\032'; '\116'; '\104'; '\101'; '\032';
               '\118'; '\101'; '\114'; '\105'; '\102'; '\105'; '\101'; '\100';
               '\032'; '\112'; '\097'; '\114'; '\115'; '\101'; '\114'; '\032';
               '\114'; '\101'; '\106'; '\101'; '\099'; '\116'; '\115'; '\032';
               '\116'; '\104'; '\101'; '\032'; '\102'; '\111'; '\114'; '\109';
               '\117'; '\108'; '\097'] @
             nl),
                                       Nat (Z.of_int 2))
                              | Some psi_0 ->
                                (let psi = input_formula conf psi_0 in
                                  (if null (c_sig conf)
                                    then Done
   ([], otxt (usage_string @ nl), Nat (Z.of_int 2))
                                    else NeedFile
   ((fun cs -> String.of_seq (List.to_seq cs)) (c_sig conf),
     (fun stext ->
       (match read_sig (string_of_bytes stext)
         with Inl e -> Done ([], otxt (sig_error_msg e @ nl), Nat (Z.of_int 2))
         | Inr a -> start_monitor conf pf psi a))))))))))
      | CExit (out, e, a) -> Done (otxt out, otxt e, a));;

let rec dq_len d = plus_nata (dq_nf d) (dq_nb d);;

let rec dq_nth
  d k = (if less_nat k (dq_nf d) then nth (dq_f d) k
          else nth (dq_b d)
                 (minus_nata (minus_nata (dq_nb d) one_nata)
                   (minus_nata k (dq_nf d))));;

let rec list_update
  x0 i y = match x0, i, y with [], i, y -> []
    | x :: xs, i, y ->
        (if equal_nata i zero_nata then y :: xs
          else x :: list_update xs (minus_nata i one_nata) y);;

let rec dq_upd
  d k x =
    (if less_nat k (dq_nf d)
      then Dq (list_update (dq_f d) k x, dq_b d, dq_nf d, dq_nb d)
      else Dq (dq_f d,
                list_update (dq_b d)
                  (minus_nata (minus_nata (dq_nb d) one_nata)
                    (minus_nata k (dq_nf d)))
                  x,
                dq_nf d, dq_nb d));;

let rec map
  f x1 = match f, x1 with f, Empty -> Empty
    | f, Branch (c, lt, k, v, rt) -> Branch (c, map f lt, k, f k v, map f rt);;

let rec mapb _A xb xc = Mapping_RBTa (map xb (impl_ofa _A xc));;

let rec keysc (_A1, _A2, _A3) xa = set (_A1, _A2, _A3) (mapa fst (impl_of xa));;

let rec keys (_A1, _A2, _A3, _A4)
  = function RBT_Mapping t -> RBT_set (mapb _A3 (fun _ _ -> ()) t)
    | Assoc_List_Mapping al -> keysc (_A2, _A3, _A4) al
    | Mapping m -> collect _A1 (fun k -> not (is_none (m k)));;

let rec image_filter (_A1, _A2) (_B1, _B2, _B3)
  h x1 = match h, x1 with
    h, RBT_set rbt ->
      (match ccompare _A2
        with None ->
          failwith "Option.image_filter RBT_set: ccompare = None"
            (fun _ -> image_filter (_A1, _A2) (_B1, _B2, _B3) h (RBT_set rbt))
        | Some _ ->
          foldb _A2
            (fun x a ->
              (match h x with None -> a | Some y -> insert (_B1, _B2) y a))
            rbt (bot_set (_B1, _B2, _B3)))
    | g, DList_set dxs ->
        (match ceq _A1
          with None ->
            failwith "Option.image_filter DList_set: ceq = None"
              (fun _ ->
                image_filter (_A1, _A2) (_B1, _B2, _B3) g (DList_set dxs))
          | Some _ ->
            foldc _A1
              (fun x a ->
                (match g x with None -> a | Some y -> insert (_B1, _B2) y a))
              dxs (bot_set (_B1, _B2, _B3)))
    | f, Set_Monad xs -> Set_Monad (map_filter f xs);;

let rec these (_A1, _A2, _A3)
  a = image_filter ((ceq_option _A1), (ccompare_option _A2)) (_A1, _A2, _A3)
        (fun x -> x) a;;

let rec mkr p g v = take p g @ v :: drop p g;;

let rec map_valuesa
  xb xc = Alist (mapa (fun (x, y) -> (x, xb x y)) (impl_of xc));;

let rec map_values _A
  f x1 = match f, x1 with
    f, RBT_Mapping t ->
      (match ccompare _A
        with None ->
          failwith "map_values RBT_Mapping: ccompare = None"
            (fun _ -> map_values _A f (RBT_Mapping t))
        | Some _ -> RBT_Mapping (mapb _A f t))
    | f, Assoc_List_Mapping al -> Assoc_List_Mapping (map_valuesa f al)
    | f, Mapping m -> Mapping (fun k -> map_option (f k) (m k));;

let rec nsumm
  m = map_values (ccompare_list ccompare_event_data) (fun _ -> fst) m;;

let rec rax = function UFlat (c, ax) -> ax
              | UNCnt m -> Some (GCnt (nsumm m))
              | UNSum m -> Some (GSum (nsumm m));;

