    | k, v, Assoc_List_Mapping al ->
        Assoc_List_Mapping (updatea (equal_list equal_event_data) k v al)
    | k, v, Mapping m ->
        Mapping (fun_upd (equal_list equal_event_data) m k (Some v));;

