let rec edl_gstep_del
  k ev t ax =
    (match ax with None -> None
      | Some (GCnt m) ->
        (match edl_gd_cnt k t (true, m) with (true, ma) -> Some (GCnt ma)
          | (false, _) -> None)
      | Some (GSum m) ->
        (match edl_gd_sum k ev t (true, m) with (true, ma) -> Some (GSum ma)
          | (false, _) -> None)
      | Some (GRank (m, ty)) ->
