let rec ed_cmp x = the ccompare_event_dataa x;;

let rec ed_out
  ff d =
    (match d with EInt i -> [Verimon_runtime.dec_of_z i] | EFloat f -> [ff f]
      | EString s ->
        (if Stdlib.(=) s "" then [id "\034\034"]
          else (if (fun s -> let n = String.length s in n > 0 && String.get s 0 = Char.chr 34 && String.get s (n - 1) = Char.chr 34)
                     s
                 then [s] else [id "\034"; s; id "\034"])));;

let rec mp_ed_cmp a b = match a, b with EString uu, EFloat uv -> Lt
                    | EFloat uw, EString ux -> Gt
                    | EInt v, b -> ed_cmp (EInt v) b
                    | EFloat v, EInt va -> ed_cmp (EFloat v) (EInt va)
                    | EFloat v, EFloat va -> ed_cmp (EFloat v) (EFloat va)
                    | a, EInt v -> ed_cmp a (EInt v)
                    | EString va, EString v -> ed_cmp (EString va) (EString v);;

let rec mp_cmp
  x0 x1 = match x0, x1 with [], [] -> Eqa
    | [], uu :: uv -> Lt
    | uw :: ux, [] -> Gt
    | x :: xs, y :: ys ->
        (match mp_ed_cmp x y with Eqa -> mp_cmp xs ys | Lt -> Lt | Gt -> Gt);;

let rec tp_out
  q = [id "At time point "; Verimon_runtime.dec_of_z (integer_of_nat q);
        id ":\010"];;

let rec modulo_int
  k l = Int_of_integer (modulo_integer (integer_of_int k) (integer_of_int l));;

let rec divide_int
  k l = Int_of_integer (divide_integer (integer_of_int k) (integer_of_int l));;

let rec civil_of_days
  z0 = (let z = plus_int z0 (Int_of_integer (Z.of_int 719468)) in
        let era = divide_int z (Int_of_integer (Z.of_int 146097)) in
        let doe = minus_int z (times_int era (Int_of_integer (Z.of_int 146097)))
          in
        let yoe =
          divide_int
            (minus_int
              (plus_int
                (minus_int doe
                  (divide_int doe (Int_of_integer (Z.of_int 1460))))
                (divide_int doe (Int_of_integer (Z.of_int 36524))))
              (divide_int doe (Int_of_integer (Z.of_int 146096))))
            (Int_of_integer (Z.of_int 365))
          in
        let doy =
          minus_int doe
            (minus_int
              (plus_int (times_int (Int_of_integer (Z.of_int 365)) yoe)
                (divide_int yoe (Int_of_integer (Z.of_int 4))))
              (divide_int yoe (Int_of_integer (Z.of_int 100))))
          in
        let mp =
          divide_int
            (plus_int (times_int (Int_of_integer (Z.of_int 5)) doy)
              (Int_of_integer (Z.of_int 2)))
            (Int_of_integer (Z.of_int 153))
          in
        let d =
          plus_int
            (minus_int doy
              (divide_int
                (plus_int (times_int (Int_of_integer (Z.of_int 153)) mp)
                  (Int_of_integer (Z.of_int 2)))
                (Int_of_integer (Z.of_int 5))))
            one_int
          in
        let m =
          (if less_int mp (Int_of_integer (Z.of_int 10))
            then plus_int mp (Int_of_integer (Z.of_int 3))
            else minus_int mp (Int_of_integer (Z.of_int 9)))
          in
        let y =
          plus_int
            (plus_int yoe (times_int era (Int_of_integer (Z.of_int 400))))
            (if less_eq_int m (Int_of_integer (Z.of_int 2)) then one_int
              else zero_int)
          in
         (y, (m, d)));;

let rec str8_of_int i = Verimon_runtime.dec_of_z (integer_of_int i);;

let rec unix_out
  t = (let s = int_of_nat t in
       let (y, (m, d)) =
         civil_of_days (divide_int s (Int_of_integer (Z.of_int 86400))) in
       let r = modulo_int s (Int_of_integer (Z.of_int 86400)) in
        [str8_of_int (minus_int y (Int_of_integer (Z.of_int 1900))); id "-";
          str8_of_int (minus_int m one_int); id "-"; str8_of_int d; id " ";
          str8_of_int (divide_int r (Int_of_integer (Z.of_int 3600))); id ":";
          str8_of_int
            (modulo_int (divide_int r (Int_of_integer (Z.of_int 60)))
              (Int_of_integer (Z.of_int 60)));
          id ":"; str8_of_int (modulo_int r (Int_of_integer (Z.of_int 60)))]);;

let rec ts_out
  unix t =
    (if unix then unix_out t
      else (if equal_nata t ts_max then [id "MaxTS"]
             else [Verimon_runtime.dec_of_z (integer_of_nat t)]));;

let rec unix_str
  t = (let s = int_of_nat t in
       let (y, (m, d)) =
         civil_of_days (divide_int s (Int_of_integer (Z.of_int 86400))) in
       let r = modulo_int s (Int_of_integer (Z.of_int 86400)) in
        dec_nat (nat (minus_int y (Int_of_integer (Z.of_int 1900)))) @
          ['\045'] @
            dec_nat (nat (minus_int m one_int)) @
              ['\045'] @
                dec_nat (nat d) @
                  ['\032'] @
                    dec_nat
                      (nat (divide_int r (Int_of_integer (Z.of_int 3600)))) @
                      ['\058'] @
                        dec_nat
                          (nat (modulo_int
                                 (divide_int r (Int_of_integer (Z.of_int 60)))
                                 (Int_of_integer (Z.of_int 60)))) @
                          ['\058'] @
                            dec_nat
                              (nat (modulo_int r
                                     (Int_of_integer (Z.of_int 60)))));;

let rec ts_str unix t = (if unix then unix_str t else dec_nat t);;

let rec vc_lookup (VConf (x1, x2, x3, x4)) = x3;;

let rec vc_lsig (VConf (x1, x2, x3, x4)) = x2;;

let rec vc_pf (VConf (x1, x2, x3, x4)) = x4;;

let rec istep
  x0 acc = match x0, acc with
    (v1, p1) :: (v2, p2) :: xs, acc ->
      istep xs ((Z.add (Z.mul v1 p2) v2, Z.mul p1 p2) :: acc)
    | [], acc -> rev acc @ []
    | [v], acc -> rev acc @ [v];;

let rec icombine = function [] -> Z.zero
                   | [(v, p)] -> v
                   | x :: y :: xs -> icombine (istep (x :: y :: xs) []);;

let rec idigit
  b c = (if (('\048' : char) <= c) && ((c : char) <= '\057')
          then (let d = Z.sub ((Z.of_int (Char.code c))) (Z.of_int 48) in
                 (if Z.lt d b then d else (Z.neg (Z.of_int 1))))
          else (if (('\097' : char) <= c) && ((c : char) <= '\102')
                 then (let d = Z.sub ((Z.of_int (Char.code c))) (Z.of_int 87) in
                        (if Z.lt d b then d else (Z.neg (Z.of_int 1))))
                 else (if (('\065' : char) <= c) && ((c : char) <= '\070')
                        then (let d =
                                Z.sub ((Z.of_int (Char.code c))) (Z.of_int 55)
                                in
                               (if Z.lt d b then d else (Z.neg (Z.of_int 1))))
                        else (Z.neg (Z.of_int 1)))));;

let rec icollect
  s n b i acc =
    (if Z.lt i n
      then (if ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                   s i) : char) = '\095')
             then icollect s n b (Z.add i (Z.of_int 1)) acc
             else (let d =
                     idigit b
                       ((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                         s i)
                     in
                    (if Z.lt d Z.zero then None
                      else icollect s n b (Z.add i (Z.of_int 1)) (d :: acc))))
      else Some acc);;

let rec idigits
  s n b i acc =
    (if (fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
          i n
      then (let c =
              (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                s i
              in
             (if ((c : char) = '\095')
               then idigits s n b
                      ((fun i -> if Obj.is_int (Obj.repr i) && (Obj.magic i : Stdlib.Int.t) < max_int then Z.of_int ((Obj.magic i : Stdlib.Int.t) + 1) else Z.succ i)
                        i)
                      acc
               else (let d = idigit b c in
                      (if Z.lt d Z.zero then (Z.neg (Z.of_int 1))
                        else idigits s n b
                               ((fun i -> if Obj.is_int (Obj.repr i) && (Obj.magic i : Stdlib.Int.t) < max_int then Z.of_int ((Obj.magic i : Stdlib.Int.t) + 1) else Z.succ i)
                                 i)
                               (Z.add (Z.mul b acc) d)))))
      else acc);;

let rec inat_of_digits
  s n b i =
    (if Z.lt i n
      then (if ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                   s i) : char) = '\095')
             then None
             else (if Z.leq (Z.sub n i) (Z.of_int 256)
                    then (let r = idigits s n b i Z.zero in
                           (if Z.lt r Z.zero then None else Some r))
                    else (match icollect s n b i [] with None -> None
                           | Some rds ->
                             Some (icombine
                                    (fold (fun d -> (fun a -> (d, b) :: a)) rds
                                      [])))))
      else None);;

let rec ibbase_of
  s n i =
    (if Z.lt (Z.add i (Z.of_int 1)) n &&
          ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
              s i) : char) = '\048')
      then (let x =
              (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                s (Z.add i (Z.of_int 1))
              in
             (if ((x : char) = '\120') || ((x : char) = '\088')
               then ((Z.of_int 16), Z.add i (Z.of_int 2))
               else (if ((x : char) = '\111') || ((x : char) = '\079')
                      then ((Z.of_int 8), Z.add i (Z.of_int 2))
                      else (if ((x : char) = '\098') || ((x : char) = '\066')
                             then ((Z.of_int 2), Z.add i (Z.of_int 2))
                             else ((Z.of_int 10), i)))))
      else ((Z.of_int 10), i));;

let rec ddigits
  s n i acc =
    (if (fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
          i n
      then (let c =
              (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                s i
              in
             (if (('\048' : char) <= c) && ((c : char) <= '\057')
               then ddigits s n
                      ((fun i -> if Obj.is_int (Obj.repr i) && (Obj.magic i : Stdlib.Int.t) < max_int then Z.of_int ((Obj.magic i : Stdlib.Int.t) + 1) else Z.succ i)
                        i)
                      (Z.add (Z.mul acc (Z.of_int 10))
                        (Z.sub ((Z.of_int (Char.code c))) (Z.of_int 48)))
               else (if ((c : char) = '\095')
                      then ddigits s n
                             ((fun i -> if Obj.is_int (Obj.repr i) && (Obj.magic i : Stdlib.Int.t) < max_int then Z.of_int ((Obj.magic i : Stdlib.Int.t) + 1) else Z.succ i)
                               i)
                             acc
                      else (Z.neg (Z.of_int 1)))))
      else acc);;

let rec iunsigned
  s n i =
    (if (fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
          i n &&
          ((fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
             n ((fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) && (let a = (Obj.magic i : Stdlib.Int.t) and b = (Obj.magic j : Stdlib.Int.t) in let c = a + b in (c lxor a) land (c lxor b) >= 0) then Z.of_int ((Obj.magic i : Stdlib.Int.t) + (Obj.magic j : Stdlib.Int.t)) else Z.add i j)
                 i (Z.of_int 257)) &&
            ((('\049' : char) <= ((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                                   s i)) &&
              ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                  s i) : char) <= '\057')))
      then (let r = ddigits s n i Z.zero in
             (if (fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
                   r Z.zero
               then None else Some r))
      else (let (a, b) = ibbase_of s n i in inat_of_digits s n a b));;

let rec ibint_of
  s = (let n = (Z.of_int (String.length s)) in
        (if (fun i j -> if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) then (Obj.magic i : Stdlib.Int.t) < (Obj.magic j : Stdlib.Int.t) else Z.lt i j)
              Z.zero n
          then (let c =
                  (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                    s Z.zero
                  in
                 (if ((c : char) = '\045')
                   then map_option Z.neg (iunsigned s n (Z.of_int 1))
                   else (if ((c : char) = '\043')
                          then iunsigned s n (Z.of_int 1)
                          else iunsigned s n Z.zero)))
          else None));;

let rec conv_field
  pf t f =
    (match t with TInt -> map_option (fun a -> EInt a) (ibint_of f)
      | TFloat -> map_option (fun a -> EFloat a) (pf f)
      | TString -> Some (EString ((fun x -> x) f)));;

let rec conv_fields_a
  pf uu uv acc = match pf, uu, uv, acc with
    pf, t :: ts, f :: fs, acc ->
      (match conv_field pf t f with None -> Inl (size_lista acc, t)
        | Some x -> conv_fields_a pf ts fs (x :: acc))
    | pf, [], uv, acc -> Inr (rev acc)
    | pf, uu, [], acc -> Inr (rev acc);;

let rec conv_event
  pf l e =
    (let (p, fs) = e in
     let q = (fun x -> x) p in
     let m = nat_of_integer (ilen Z.zero fs) in
      (match l (q, m) with None -> Inl (VE_PREDICATE (p, m))
        | Some tys ->
          map_sum (fun (a, b) -> VE_FIELD (p, a, b)) (fun a -> (q, a))
            (conv_fields_a pf tys fs [])));;

let rec conv_events_acc
  pf l acc x3 = match pf, l, acc, x3 with pf, l, acc, [] -> Inr (rev acc)
    | pf, l, acc, e :: es ->
        (match conv_event pf l e with Inl a -> Inl a
          | Inr x -> conv_events_acc pf l (x :: acc) es);;

let rec conv_events pf l es = conv_events_acc pf l [] es;;

let rec pred_error
  s x1 = match s, x1 with s, [] -> None
    | s, (p, fs) :: es ->
        (if list_ex (fun (q, _) -> String.equal q ((fun x -> x) p)) s
          then pred_error s es else Some (VE_PREDICATE (p, size_lista fs)));;

let rec conv_fields
  pf uu uv i = match pf, uu, uv, i with
    pf, t :: ts, f :: fs, i ->
      (match conv_field pf t f with None -> Inl (i, t)
        | Some x -> map_sum id (fun a -> x :: a) (conv_fields pf ts fs (suc i)))
    | pf, [], uv, i -> Inr []
    | pf, uu, [], i -> Inr [];;

let rec conv_error
  pf l s x3 = match pf, l, s, x3 with pf, l, s, [] -> None
    | pf, l, s, (p, fs) :: es ->
        (let q = (fun x -> x) p in
          (match l (q, size_lista fs)
            with None ->
              (match find (fun (qa, _) -> String.equal qa q) s
                with None -> Some (VE_PREDICATE (p, size_lista fs))
                | Some (_, tys) ->
                  (match conv_fields pf tys fs zero_nata
                    with Inl (i, t) -> Some (VE_FIELD (p, i, t))
                    | Inr _ -> Some (VE_PREDICATE (p, size_lista fs))))
            | Some tys ->
              (match conv_fields pf tys fs zero_nata
                with Inl (i, t) -> Some (VE_FIELD (p, i, t))
                | Inr _ -> conv_error pf l s es)));;

let rec bnat_of_digits
  s n b i =
    (if Z.lt i n
      then (if ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                   s i) : char) = '\095')
             then None
             else (if Z.leq (Z.sub n i) (Z.of_int 256)
                    then (let r = idigits s n (integer_of_nat b) i Z.zero in
                           (if Z.lt r Z.zero then None
                             else Some (nat_of_integer r)))
                    else (match icollect s n (integer_of_nat b) i []
                           with None -> None
                           | Some rds ->
                             Some (nat_of_integer
                                    (icombine
                                      (fold
(fun d -> (fun a -> (d, integer_of_nat b) :: a)) rds []))))))
      else None);;

let rec bbase_of
  s n i =
    (if Z.lt (Z.add i (Z.of_int 1)) n &&
          ((((fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
              s i) : char) = '\048')
      then (let x =
              (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                s (Z.add i (Z.of_int 1))
              in
             (if ((x : char) = '\120') || ((x : char) = '\088')
               then (Nat (Z.of_int 16), Z.add i (Z.of_int 2))
               else (if ((x : char) = '\111') || ((x : char) = '\079')
                      then (Nat (Z.of_int 8), Z.add i (Z.of_int 2))
                      else (if ((x : char) = '\098') || ((x : char) = '\066')
                             then (Nat (Z.of_int 2), Z.add i (Z.of_int 2))
                             else (Nat (Z.of_int 10), i)))))
      else (Nat (Z.of_int 10), i));;

let rec bunsigned
  s n i = (let (a, b) = bbase_of s n i in bnat_of_digits s n a b);;

let rec bint_of
  s = (let n = (Z.of_int (String.length s)) in
        (if Z.lt Z.zero n
          then (let c =
                  (fun s i -> String.get s (if Obj.is_int (Obj.repr i) then (let k = (Obj.magic i : Stdlib.Int.t) in if k < 0 then 0 else k)
      else if Z.sign i < 0 then 0 else Z.to_int i))
                    s Z.zero
                  in
                 (if ((c : char) = '\045')
                   then map_option (fun na -> uminus_int (int_of_nat na))
                          (bunsigned s n (Z.of_int 1))
                   else (if ((c : char) = '\043')
                          then map_option int_of_nat
                                 (bunsigned s n (Z.of_int 1))
                          else map_option int_of_nat (bunsigned s n Z.zero))))
          else None));;

let rec bnat_of
  s = (match bint_of s with None -> None
        | Some i -> (if less_eq_int zero_int i then Some (nat i) else None));;

let rec vitem
  cf x z =
    (match x
      with O_ITEM (sp, Entry (ts, evs)) ->
        (match bnat_of ts with None -> (VO_ERROR (sp, VE_TIMESTAMP ts), z)
          | Some t ->
            (match conv_events (vc_pf cf) (vc_lookup cf) evs
              with Inl e ->
                (VO_ERROR
                   (sp, (match pred_error (vc_lsig cf) evs
                          with None ->
                            (if less_nat t (snd z) then VE_ORDER (t, snd z)
                              else (match
                                     conv_error (vc_pf cf) (vc_lookup cf)
                                       (vc_lsig cf) evs
                                     with None -> e | Some ea -> ea))
                          | Some ea -> ea)),
                  z)
              | Inr xs -> vtp sp xs t z))
      | O_ITEM (sp, Command (c, _)) -> (VO_ERROR (sp, VE_COMMAND c), z)
      | O_ERROR (pos, e) -> (VO_ERROR (pos, VE_PARSE e), z));;

let rec vc_skip (VConf (x1, x2, x3, x4)) = x1;;

let rec vkeep cf b = not (vc_skip cf ((fun x -> x) b));;

let rec ed_fold
  ff fi f d acc =
    (match d with EInt i -> fi i acc | EFloat x -> f (ff x) acc
      | EString s ->
        (if Stdlib.(=) s "" then f (id "\034\034") acc
          else (if (fun s -> let n = String.length s in n > 0 && String.get s 0 = Char.chr 34 && String.get s (n - 1) = Char.chr 34)
                     s
                 then f s acc else f (id "\034") (f s (f (id "\034") acc)))));;

let rec adj_sorted
  r x1 = match r, x1 with r, x :: y :: zs -> r x y && adj_sorted r (y :: zs)
    | r, [] -> true
    | r, [v] -> true;;

let rec rows_of
  x = (let l = edl_csorted_list_of_set x in
        (if adj_sorted (fun a b -> equal_order (mp_cmp a b) Lt) l then l
          else csort mp_cmp l));;

let rec sep_out d x1 = match d, x1 with d, [] -> []
                  | d, [x] -> x
                  | d, x :: y :: zs -> x @ d :: sep_out d (y :: zs);;

let rec vitems_acc
  cf x1 z acc = match cf, x1, z, acc with cf, [], z, acc -> (rev acc, z)
    | cf, x :: xs, z, acc ->
        (let (v, st1) = vitem cf x z in vitems_acc cf xs st1 (v :: acc));;

let rec vitems cf xs z = vitems_acc cf xs z [];;

let rec sep_fold
  g d f x3 acc = match g, d, f, x3, acc with g, d, f, [], acc -> acc
    | g, d, f, [x], acc -> g x acc
    | g, d, f, x :: y :: zs, acc -> sep_fold g d f (y :: zs) (f d (g x acc));;

let rec fparse_finish
  = function F_INIT -> Some []
    | F_DB (ts, evs) -> Some [Entry (ts, rev evs)]
    | F_NAME (ts, evs, p) -> Some [Entry (ts, rev ((p, []) :: evs))]
    | F_TUPLES (ts, evs, p) -> Some [Entry (ts, rev evs)]
    | F_SKIP (ts, evs) -> Some [Entry (ts, rev evs)]
    | F_TS -> None
    | F_FIELD1 (v, va, vb) -> None
    | F_AFTER (v, va, vb, vc) -> None
    | F_FIELDN (v, va, vb, vc) -> None
    | F_SFIELD1 (v, va) -> None
    | F_SAFTER (v, va) -> None
    | F_SFIELDN (v, va) -> None
    | F_CMD -> None
    | F_ARGS (v, va) -> None;;

let rec efinish_p
  b p sp acc =
    (match p with None -> acc
      | Some ps ->
        (match fparse_finish ps
          with None -> O_ERROR (b, E_TOKEN (expect_of ps, None)) :: acc
          | Some es -> fold (fun e -> (fun a -> O_ITEM (sp, e) :: a)) es acc));;

let rec efinish
  k st =
    (match st with (b, (E_INIT, (p, sp))) -> rev (efinish_p b p sp [])
      | (b, (E_SIMPLE (pre, _, tp), (p, sp))) ->
        (let (acc, pa) =
           efeed k (T_STR ((String.concat "" (rev pre)))) tp p sp [] in
          rev (efinish_p b pa (start tp pa sp) acc))
      | (_, (E_QUOTED (_, _, tp), (_, _))) -> [O_ERROR (tp, E_UNTERMINATED)]
      | (_, (E_ESCAPE (_, _, tp), (_, _))) -> [O_ERROR (tp, E_UNTERMINATED)]
      | (b, (E_COMMENT, (p, sp))) -> rev (efinish_p b p sp []));;

let rec vfinish
  cf fin z =
    (let (vs, mst) = vitems cf (efinish (vkeep cf) (fst z)) (snd z) in
      vs @ (match fin with None -> []
             | Some t -> [fst (vtp (fst (fst z)) [] t mst)]));;

let rec string_of_expect
  = function
    X_ENTRY ->
      squote ['\064'] @ ['\032'; '\111'; '\114'; '\032'] @ squote ['\062']
    | X_TIMESTAMP ->
        ['\097'; '\032'; '\116'; '\105'; '\109'; '\101'; '\045'; '\115'; '\116';
          '\097'; '\109'; '\112']
    | X_PREDICATE ->
        ['\097'; '\032'; '\112'; '\114'; '\101'; '\100'; '\105'; '\099'; '\097';
          '\116'; '\101'; '\044'; '\032'] @
          squote ['\064'] @
            ['\044'; '\032'] @
              squote ['\059'] @
                ['\044'; '\032'; '\111'; '\114'; '\032'] @ squote ['\062']
    | X_FIELD_OR_RPAREN ->
        ['\097'; '\032'; '\116'; '\117'; '\112'; '\108'; '\101'; '\032'; '\102';
          '\105'; '\101'; '\108'; '\100'; '\032'; '\111'; '\114'; '\032'] @
          squote ['\041']
    | X_COMMA_OR_RPAREN ->
        squote ['\044'] @ ['\032'; '\111'; '\114'; '\032'] @ squote ['\041']
    | X_FIELD ->
        ['\097'; '\032'; '\116'; '\117'; '\112'; '\108'; '\101'; '\032'; '\102';
          '\105'; '\101'; '\108'; '\100']
    | X_CMD_NAME ->
        ['\097'; '\032'; '\099'; '\111'; '\109'; '\109'; '\097'; '\110'; '\100';
          '\032'; '\110'; '\097'; '\109'; '\101']
    | X_CMD_ARG ->
        ['\097'; '\032'; '\099'; '\111'; '\109'; '\109'; '\097'; '\110'; '\100';
          '\032'; '\097'; '\114'; '\103'; '\117'; '\109'; '\101'; '\110';
          '\116'; '\032'; '\111'; '\114'; '\032'] @
          squote ['\060'];;

let rec string_of_ltok
  = function T_AT -> squote ['\064']
    | T_LPAREN -> squote ['\040']
    | T_RPAREN -> squote ['\041']
    | T_LANGLE -> squote ['\060']
    | T_RANGLE -> squote ['\062']
    | T_LBRACE -> squote ['\123']
    | T_RBRACE -> squote ['\125']
    | T_COMMA -> squote ['\044']
    | T_SEMICOLON -> squote ['\059']
    | T_STR s -> '\034' :: escaped (string_of_bytes s) @ ['\034'];;

let rec char_escaped
  c = (if ((c : char) = '\039') then ['\092'; '\039'] else escaped_char c);;

let rec perror_msg
  = function
    E_TOKEN (x, Some t) ->
      ['\069'; '\120'; '\112'; '\101'; '\099'; '\116'; '\101'; '\100'; '\032'] @
        string_of_expect x @
          ['\032'; '\098'; '\117'; '\116'; '\032'; '\115'; '\097'; '\119';
            '\032'] @
            string_of_ltok t
    | E_TOKEN (x, None) ->
        ['\069'; '\120'; '\112'; '\101'; '\099'; '\116'; '\101'; '\100';
          '\032'] @
          string_of_expect x @
            ['\032'; '\098'; '\117'; '\116'; '\032'; '\115'; '\097'; '\119';
              '\032'; '\060'; '\069'; '\079'; '\070'; '\062']
    | E_CHAR (x, c) ->
        ['\069'; '\120'; '\112'; '\101'; '\099'; '\116'; '\101'; '\100';
          '\032'] @
          string_of_expect x @
            ['\032'; '\098'; '\117'; '\116'; '\032'; '\115'; '\097'; '\119';
              '\032'; '\060'; '\117'; '\110'; '\114'; '\101'; '\099'; '\111';
              '\103'; '\110'; '\105'; '\122'; '\101'; '\100'; '\062'; '\032';
              '\040'] @
              char_escaped c @ ['\041']
    | E_UNTERMINATED ->
        ['\085'; '\110'; '\116'; '\101'; '\114'; '\109'; '\105'; '\110'; '\097';
          '\116'; '\101'; '\100'; '\032'; '\113'; '\117'; '\111'; '\116';
          '\101'; '\100'; '\032'; '\115'; '\116'; '\114'; '\105'; '\110';
          '\103'];;

let rec lsig_arity
  l p = map_option size_lista (map_of equal_string8 l ((fun x -> x) p));;

let rec log_error
  unix l x2 = match unix, l, x2 with
    unix, l, VE_PARSE e -> LE_LOC (perror_msg e)
    | unix, l, VE_TIMESTAMP ts ->
        LE_LOC
          (['\067'; '\097'; '\110'; '\110'; '\111'; '\116'; '\032'; '\099';
             '\111'; '\110'; '\118'; '\101'; '\114'; '\116'; '\032'] @
            string_of_bytes ts @
              ['\032'; '\105'; '\110'; '\116'; '\111'; '\032'; '\097'; '\032';
                '\116'; '\105'; '\109'; '\101'; '\115'; '\116'; '\097'; '\109';
                '\112'])
    | unix, l, VE_ORDER (t, p) ->
        LE_ORDER
          (['\069'; '\082'; '\082'; '\079'; '\082'; '\058'; '\032'; '\079';
             '\117'; '\116'; '\032'; '\111'; '\102'; '\032'; '\111'; '\114';
             '\100'; '\101'; '\114'; '\032'; '\116'; '\105'; '\109'; '\101';
             '\115'; '\116'; '\097'; '\109'; '\112'; '\032'] @
            ts_str unix t @
              ['\032'; '\040'; '\112'; '\114'; '\101'; '\118'; '\105'; '\111';
                '\117'; '\115'; '\058'; '\032'] @
                ts_str unix p @ ['\041'])
    | unix, l, VE_PREDICATE (p, n) ->
        LE_LOC
          (match lsig_arity l p
            with None ->
              ['\080'; '\114'; '\101'; '\100'; '\105'; '\099'; '\097'; '\116';
                '\101'; '\032'] @
                string_of_bytes p @
                  ['\032'; '\119'; '\097'; '\115'; '\032'; '\110'; '\111';
                    '\116'; '\032'; '\100'; '\101'; '\102'; '\105'; '\110';
                    '\101'; '\100'; '\032'; '\105'; '\110'; '\032'; '\116';
                    '\104'; '\101'; '\032'; '\115'; '\105'; '\103'; '\110';
                    '\097'; '\116'; '\117'; '\114'; '\101'; '\046']
            | Some a ->
              ['\087'; '\114'; '\111'; '\110'; '\103'; '\032'; '\116'; '\117';
                '\112'; '\108'; '\101'; '\032'; '\108'; '\101'; '\110'; '\103';
                '\116'; '\104'; '\032'; '\102'; '\111'; '\114'; '\032'; '\112';
                '\114'; '\101'; '\100'; '\105'; '\099'; '\097'; '\116'; '\101';
                '\032'] @
                string_of_bytes p @
                  ['\032'; '\040'; '\101'; '\120'; '\112'; '\101'; '\099';
                    '\116'; '\101'; '\100'; '\058'; '\032'] @
                    dec_nat a @
                      ['\044'; '\032'; '\097'; '\099'; '\116'; '\117'; '\097';
                        '\108'; '\058'; '\032'] @
                        dec_nat n @ ['\041'])
    | unix, l, VE_FIELD (p, i, t) ->
        LE_LOC
          (['\069'; '\120'; '\112'; '\101'; '\099'; '\116'; '\101'; '\100';
             '\032'; '\116'; '\121'; '\112'; '\101'; '\032'] @
            (match t with TInt -> ['\105'; '\110'; '\116']
              | TFloat -> ['\102'; '\108'; '\111'; '\097'; '\116']
              | TString -> ['\115'; '\116'; '\114'; '\105'; '\110'; '\103']) @
              ['\032'; '\102'; '\111'; '\114'; '\032'; '\112'; '\114'; '\101';
                '\100'; '\105'; '\099'; '\097'; '\116'; '\101'; '\032'] @
                string_of_bytes p @
                  ['\044'; '\032'; '\102'; '\105'; '\101'; '\108'; '\100';
                    '\032'; '\110'; '\117'; '\109'; '\098'; '\101'; '\114';
                    '\032'] @
                    dec_nat (suc i))
    | unix, l, VE_COMMAND c ->
        LE_CMD
          ['\069'; '\082'; '\082'; '\079'; '\082'; '\058'; '\032'; '\067';
            '\111'; '\109'; '\109'; '\097'; '\110'; '\100'; '\115'; '\032';
            '\097'; '\114'; '\101'; '\032'; '\110'; '\111'; '\116'; '\032';
            '\115'; '\117'; '\112'; '\112'; '\111'; '\114'; '\116'; '\101';
            '\100'; '\032'; '\098'; '\121'; '\032'; '\116'; '\104'; '\101';
            '\032'; '\118'; '\101'; '\114'; '\105'; '\102'; '\105'; '\101';
            '\100'; '\032'; '\107'; '\101'; '\114'; '\110'; '\101'; '\108'];;

let rec tuple_out
  ff t = id "(" :: sep_out (id ",") (mapa (ed_out ff) t) @ [id ")"];;

let rec vpending
  z = (match fst z with (b, (E_INIT, _)) -> b
        | (_, (E_SIMPLE (_, _, t), _)) -> t | (_, (E_QUOTED (_, _, t), _)) -> t
        | (_, (E_ESCAPE (_, _, t), _)) -> t | (b, (E_COMMENT, _)) -> b);;

let rec tuple_fold
  ff fi f t acc =
    f (id ")") (sep_fold (ed_fold ff fi f) (id ",") f t (f (id "(") acc));;

let rec eloop k s n b i l p sp acc = floop k s n b i l p sp acc;;

let rec c_stop_first
  (Config_ext
    (c_sig, c_formula, c_log, c_negate, c_verbose, c_check, c_rw, c_mw, c_index,
      c_sigout, c_unix, c_mem, c_newlastts, c_filter, c_ignore_errors,
      c_stop_first, c_version, c_gc_space_overhead, c_gc_minor_heap, more))
    = c_stop_first;;

let rec c_unix
  (Config_ext
    (c_sig, c_formula, c_log, c_negate, c_verbose, c_check, c_rw, c_mw, c_index,
      c_sigout, c_unix, c_mem, c_newlastts, c_filter, c_ignore_errors,
      c_stop_first, c_version, c_gc_space_overhead, c_gc_minor_heap, more))
    = c_unix;;

let rec verdict_out
  cfg ff n q t x =
    (let rows =
       (if c_stop_first cfg then take one_nata (rows_of x) else rows_of x) in
     let head =
       id "@" ::
         ts_out (c_unix cfg) t @
           [id " (time point "; Verimon_runtime.dec_of_z (integer_of_nat q);
             id "): "]
       in
     let nl8 = id "\010" in
      ((if c_verbose cfg
         then (if equal_nata n zero_nata
                then head @ [(if null rows then id "false" else id "true"); nl8]
                else head @
                       id "(" ::
                         sep_out (id ",") (mapa (tuple_out ff) rows) @
                           [id ")"; nl8])
         else (if null rows then []
                else (if equal_nata n zero_nata then head @ [id "true"; nl8]
                       else head @
                              sep_out (id " ") (mapa (tuple_out ff) rows) @
                                [nl8]))),
        not (null rows)));;

let rec verdict_fold
  conf ff n q t x fi f acc =
    (let rows =
       (if c_stop_first conf then take one_nata (rows_of x) else rows_of x) in
     let head =
       id "@" ::
         ts_out (c_unix conf) t @
           [id " (time point "; Verimon_runtime.dec_of_z (integer_of_nat q);
             id "): "]
       in
     let nl8 = id "\010" in
      ((if c_verbose conf
         then (if equal_nata n zero_nata
                then fold f
                       (head @
                         [(if null rows then id "false" else id "true"); nl8])
                       acc
                else f nl8 (f (id ")")
                             (sep_fold (tuple_fold ff fi f) (id ",") f rows
                               (f (id "(") (fold f head acc)))))
         else (if null rows then acc
                else (if equal_nata n zero_nata
                       then fold f (head @ [id "true"; nl8]) acc
                       else f nl8 (sep_fold (tuple_fold ff fi f) (id " ") f rows
                                    (fold f head acc))))),
        not (null rows)));;

let rec close_chunk
  s n l =
    (match l with E_INIT -> l
      | E_SIMPLE (pre, st, a) ->
        E_SIMPLE
          ((fun s i j -> let n = String.length s in
      if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) && 0 <= (Obj.magic i : Stdlib.Int.t)
        && (Obj.magic i : Stdlib.Int.t) <= (Obj.magic j : Stdlib.Int.t) && (Obj.magic j : Stdlib.Int.t) <= n
      then String.sub s (Obj.magic i : Stdlib.Int.t) ((Obj.magic j : Stdlib.Int.t) - (Obj.magic i : Stdlib.Int.t))
      else (let a = if Z.sign i <= 0 then 0 else if Z.lt i (Z.of_int n) then Z.to_int i else n in
        let l = Z.sub j i in
        if Z.sign l <= 0 || a >= n then ""
        else String.sub s a (if Z.lt l (Z.of_int (n - a)) then Z.to_int l else n - a)))
             s st n ::
             pre,
            Z.zero, a)
      | E_QUOTED (pre, st, a) ->
        E_QUOTED
          ((fun s i j -> let n = String.length s in
      if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) && 0 <= (Obj.magic i : Stdlib.Int.t)
        && (Obj.magic i : Stdlib.Int.t) <= (Obj.magic j : Stdlib.Int.t) && (Obj.magic j : Stdlib.Int.t) <= n
      then String.sub s (Obj.magic i : Stdlib.Int.t) ((Obj.magic j : Stdlib.Int.t) - (Obj.magic i : Stdlib.Int.t))
      else (let a = if Z.sign i <= 0 then 0 else if Z.lt i (Z.of_int n) then Z.to_int i else n in
        let l = Z.sub j i in
        if Z.sign l <= 0 || a >= n then ""
        else String.sub s a (if Z.lt l (Z.of_int (n - a)) then Z.to_int l else n - a)))
             s st n ::
             pre,
            Z.zero, a)
      | E_ESCAPE (pre, st, a) ->
        E_ESCAPE
          ((fun s i j -> let n = String.length s in
      if Obj.is_int (Obj.repr i) && Obj.is_int (Obj.repr j) && 0 <= (Obj.magic i : Stdlib.Int.t)
        && (Obj.magic i : Stdlib.Int.t) <= (Obj.magic j : Stdlib.Int.t) && (Obj.magic j : Stdlib.Int.t) <= n
      then String.sub s (Obj.magic i : Stdlib.Int.t) ((Obj.magic j : Stdlib.Int.t) - (Obj.magic i : Stdlib.Int.t))
      else (let a = if Z.sign i <= 0 then 0 else if Z.lt i (Z.of_int n) then Z.to_int i else n in
        let l = Z.sub j i in
        if Z.sign l <= 0 || a >= n then ""
        else String.sub s a (if Z.lt l (Z.of_int (n - a)) then Z.to_int l else n - a)))
             s st n ::
             pre,
            Z.zero, a)
      | E_COMMENT -> l);;

let rec efeed_chunk
  k s st =
    (let (b, (l, (p, sp))) = st in
     let n = (Z.of_int (String.length s)) in
     let (acc, (la, (pa, spa))) = eloop k s n b Z.zero l p sp [] in
      (rev acc, (Z.add b n, (close_chunk s n la, (pa, spa)))));;

let rec vfeed_chunk
  cf s z =
    (let (xs, est) = efeed_chunk (vkeep cf) s (fst z) in
     let (vs, mst) = vitems cf xs (snd z) in
      (vs, (est, mst)));;

